/// A form-root property that names one of the form's own items by id.
///
/// The name comes from the form's own item table; an id the table does not
/// carry keeps the platform's dangling `<id>:<form-item class uuid>` spelling
/// rather than dropping the property, exactly as a picture or a command the
/// reader cannot name does. See `FormRootItemReferenceSchema` for the corpus.
fn extract_form_root_item_reference(
    fields: &[&str],
    property_bag_key: &'static str,
    item_name_by_id: &BTreeMap<String, String>,
) -> Option<String> {
    let schema = FormRootItemReferenceSchema::from_raw_layout(
        fields.first().map(|field| field.trim()),
        property_bag_key,
    )?;
    let value = form_root_property_bag_value(fields, schema.property_bag_key())?;
    let value_fields = split_1c_braced_fields(value.trim(), 0)?;
    let item_id = schema.item_id(&value_fields)?;
    Some(
        item_name_by_id
            .get(&item_id)
            .cloned()
            .unwrap_or_else(|| format!("{item_id}:{FORM_ITEM_TYPE_UUID}")),
    )
}

/// The metadata object or form root field 8 names as the form's settings
/// storage. A uuid the reference index does not carry stays unread rather than
/// being spelled out: every one of the 20 evidenced roots resolves, so a miss
/// is unproven rather than a dangling reference the platform would spell.
pub(super) fn extract_form_settings_storage(
    fields: &[&str],
    reference_index: &BTreeMap<String, String>,
) -> Option<String> {
    let schema = FormRootSettingsStorageSchema::from_raw_layout(
        fields.first().map(|field| field.trim()),
        fields.len(),
    )?;
    let uuid = parse_non_zero_uuid(fields.get(schema.slot())?.trim())?;
    reference_index.get(&uuid).cloned()
}

pub(super) fn extract_form_custom_settings_folder(
    fields: &[&str],
    item_name_by_id: &BTreeMap<String, String>,
) -> Option<String> {
    extract_form_root_item_reference(
        fields,
        FormRootItemReferenceSchema::CUSTOM_SETTINGS_FOLDER_KEY,
        item_name_by_id,
    )
}

pub(super) fn extract_form_group_list(
    fields: &[&str],
    item_name_by_id: &BTreeMap<String, String>,
) -> Option<String> {
    extract_form_root_item_reference(
        fields,
        FormRootItemReferenceSchema::GROUP_LIST_KEY,
        item_name_by_id,
    )
}

pub(super) fn extract_form_show_title(fields: &[&str]) -> Option<bool> {
    // Base slot 17 plus the trailer's declared optional-block count, the same
    // rule every other root trailer property follows. The previous reading
    // keyed the slot off the trailer's length alone -- 24 -> 17, 25 -> 18 --
    // which is right for root `50` but silently wrong for root `49`, whose
    // 24-member trailer declares a count of 1 and so keeps the flag at 18.
    // Slot 17 holds the constant `100` on all 1 548 root `49` forms on the
    // stand, so the property was never emitted for any of them; slot 18
    // separates `0` -> false from `1` -> absent with no counter-example.
    let tail_start = form_root_trailer_start(fields)?;
    let blocks = form_root_trailer_optional_blocks(
        fields.first().map(|field| field.trim()),
        fields.get(tail_start..)?,
    )?;
    match fields
        .get(tail_start + 17 + blocks)
        .map(|field| field.trim())?
    {
        "0" => Some(false),
        _ => None,
    }
}

pub(super) fn extract_form_show_close_button(fields: &[&str]) -> Option<bool> {
    let tail_start = form_root_trailer_start(fields)?;
    let blocks = form_root_trailer_optional_blocks(
        fields.first().map(|field| field.trim()),
        fields.get(tail_start..)?,
    )?;
    match fields
        .get(tail_start + 18 + blocks)
        .map(|field| field.trim())?
    {
        "0" => Some(false),
        _ => None,
    }
}

pub(super) fn extract_form_mobile_device_command_bar_content(
    fields: &[&str],
    item_name_by_id: &BTreeMap<String, String>,
) -> Vec<String> {
    let Some(tail_start) = form_root_trailer_start(fields) else {
        return Vec::new();
    };
    let Some(trailer) = fields.get(tail_start..) else {
        return Vec::new();
    };
    let Some(blocks) =
        form_root_trailer_optional_blocks(fields.first().map(|field| field.trim()), trailer)
    else {
        return Vec::new();
    };
    let Some(content) = trailer
        .get(FormRootMobileDeviceCommandBarContentSchema::CONTENT_TRAILER_SLOT + blocks)
        .and_then(|field| split_1c_braced_fields(field.trim(), 0))
    else {
        return Vec::new();
    };
    let Some(declared_item_count) = content
        .get(1)
        .and_then(|field| field.trim().parse::<usize>().ok())
    else {
        return Vec::new();
    };
    let parsed_ids = content
        .get(2..)
        .unwrap_or_default()
        .chunks_exact(2)
        .filter_map(|pair| {
            if pair.first()?.trim() != "\"\"" {
                return None;
            }
            let value = split_1c_braced_fields(pair.get(1)?.trim(), 0)?;
            if value.len() != 2 || value.first()?.trim() != "\"N\"" {
                return None;
            }
            let id = value.get(1)?.trim();
            id.parse::<u64>().ok().map(|_| id.to_string())
        })
        .collect::<Vec<_>>();
    let Some(schema) = FormRootMobileDeviceCommandBarContentSchema::from_raw_layout(
        fields.first().map(|field| field.trim()),
        trailer,
        content.first().map(|field| field.trim()),
        content.len(),
        declared_item_count,
        parsed_ids.len(),
    ) else {
        return Vec::new();
    };
    if schema.item_count() != parsed_ids.len() {
        return Vec::new();
    }
    let mut items = Vec::with_capacity(schema.item_count());
    for id in parsed_ids {
        if id == "0" {
            items.push(String::new());
        } else if let Some(name) = item_name_by_id.get(&id) {
            items.push(name.clone());
        } else {
            return Vec::new();
        }
    }
    items
}

pub(super) fn form_root_uses_property_bag(fields: &[&str]) -> bool {
    fields
        .get(18)
        .and_then(|field| field.trim().parse::<usize>().ok())
        .is_some_and(|count| count > 1)
        && fields
            .get(19)
            .is_some_and(|field| field.trim().parse::<usize>().is_ok())
}

pub(super) fn form_root_property_bag_value<'a>(
    fields: &'a [&str],
    property_key: &str,
) -> Option<&'a str> {
    form_root_property_bag_entry(fields, property_key).flatten()
}

/// The bag walk, keeping "the bag is unreadable" apart from "the bag is
/// readable and has no such key". The two are the same answer to a reader of
/// one value and different answers to a reader that has a default to apply:
/// a default belongs to an entry the bag declares absent, never to a bag
/// nobody could read.
pub(super) fn form_root_property_bag_entry<'a>(
    fields: &'a [&str],
    property_key: &str,
) -> Option<Option<&'a str>> {
    let schema = FormRootPropertyBagSchema::from_raw_layout(
        fields.get(FormRootPropertyBagSchema::COUNT_SLOT).copied(),
        fields.len(),
    )?;
    let mut found = None;
    for entry_index in 0..schema.entry_count() {
        let key_slot = schema.key_slot(entry_index);
        let key = fields.get(key_slot)?.trim();
        // Every key in the walk is an integer in all 5 075 attributable UT
        // roots; a non-integer means the field 18 count was not a count and the
        // whole bag is unreadable rather than partially readable.
        if key.parse::<usize>().is_err() {
            return None;
        }
        if key == property_key {
            found = Some(*fields.get(key_slot + 1)?);
        }
    }
    Some(found)
}

/// The bare-suffix spelling of the one fact table, plus the one name that is
/// not a property of the uuid at all.
///
/// `32df4349-…` is `WriteAndClose` everywhere except on a business process or a
/// task, where the platform writes `ExecuteAndClose` for the same uuid. That is
/// a property of the owner, not of the uuid, so it stays here rather than being
/// pushed into the table of uuid facts.
pub(super) fn form_standard_excluded_command_name(
    uuid: &str,
    business_process_or_task: bool,
) -> Option<&'static str> {
    if business_process_or_task && uuid == "32df4349-2607-4c2b-a4b9-bca4a1a28bd7" {
        return Some("ExecuteAndClose");
    }
    form_standard_command_suffix(uuid)
}

pub(super) fn extract_form_auto_command_bar(
    fields: &[&str],
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    standard_command_owner_name_by_id: &BTreeMap<String, FormStandardCommandOwner>,
    command_source_owner_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    metadata_command_facts: &FormOwnerScopedBindingIndexes,
) -> Option<FormAutoCommandBar> {
    find_form_auto_command_bar(
        fields,
        commands,
        object_refs,
        attribute_names_by_id,
        attribute_metadata_owners_by_id,
        table_name_by_id,
        standard_command_owner_name_by_id,
        command_source_owner_name_by_id,
        table_column_names_by_id,
        type_link_data_path_by_table_column,
        metadata_command_facts,
    )
}

pub(super) fn find_form_auto_command_bar(
    fields: &[&str],
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    standard_command_owner_name_by_id: &BTreeMap<String, FormStandardCommandOwner>,
    command_source_owner_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    metadata_command_facts: &FormOwnerScopedBindingIndexes,
) -> Option<FormAutoCommandBar> {
    for field in fields {
        let field = field.trim();
        if !field.starts_with('{') {
            continue;
        }
        let Some(nested) = split_1c_braced_fields(field, 0) else {
            continue;
        };
        if let Some(command_bar) = parse_form_auto_command_bar_fields(
            &nested,
            commands,
            object_refs,
            attribute_names_by_id,
            attribute_metadata_owners_by_id,
            table_name_by_id,
            standard_command_owner_name_by_id,
            command_source_owner_name_by_id,
            table_column_names_by_id,
            type_link_data_path_by_table_column,
            metadata_command_facts,
        ) {
            return Some(command_bar);
        }
        if let Some(command_bar) = find_form_auto_command_bar(
            &nested,
            commands,
            object_refs,
            attribute_names_by_id,
            attribute_metadata_owners_by_id,
            table_name_by_id,
            standard_command_owner_name_by_id,
            command_source_owner_name_by_id,
            table_column_names_by_id,
            type_link_data_path_by_table_column,
            metadata_command_facts,
        ) {
            return Some(command_bar);
        }
    }
    None
}

pub(super) fn parse_form_auto_command_bar_fields(
    fields: &[&str],
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
    attribute_names_by_id: &BTreeMap<String, String>,
    attribute_metadata_owners_by_id: &BTreeMap<String, FormAttributeMetadataOwner>,
    table_name_by_id: &BTreeMap<String, String>,
    standard_command_owner_name_by_id: &BTreeMap<String, FormStandardCommandOwner>,
    command_source_owner_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    metadata_command_facts_bindings: &FormOwnerScopedBindingIndexes,
) -> Option<FormAutoCommandBar> {
    let raw_fields = fields;
    let wrapper = raw_fields.first()?.trim();
    let identity = split_1c_braced_fields(raw_fields.get(1)?.trim(), 0)?;
    let id = identity.first()?.trim();
    // The same optional `UserVisible`-common prefix tuple
    // (`form_conditional_group_schema`) that the general child-item reader
    // already strips before reading a nested `AutoCommandBar`/`ContextMenu`
    // also precedes the *root* auto command bar on ERP УХ MDM_Management's
    // list forms: `{22,{-1,<uuid>},0,0,1,{0,{0,{"B",1},0}},9,"Name",…}`
    // carries the tuple at slot 5, one field ahead of where every other
    // field below assumed the `9` discriminator and the name sit. Without
    // normalizing it away first, `FormRootAutoCommandBarSchema` read the
    // tuple itself as the marker slot and refused the whole record, and the
    // form's own `<AutoCommandBar>` (and any child items it carried) went
    // unwritten -- confirmed on `Catalogs/ВнешниеИнформационныеБазы` and
    // `Catalogs/ТипыБазДанных`'s list/item forms, whose id`-1` bar is this
    // exact 30-member shape.
    let conditional_group_schema = form_conditional_group_schema(wrapper, raw_fields);
    let normalized_fields = conditional_group_schema.map(|schema| {
        let prefix_slot = schema.prefix_slot();
        raw_fields
            .iter()
            .enumerate()
            .filter_map(|(index, field)| (index != prefix_slot).then_some(*field))
            .collect::<Vec<_>>()
    });
    let fields = normalized_fields.as_deref().unwrap_or(raw_fields);
    let schema = FormRootAutoCommandBarSchema::from_raw_layout(wrapper, id, fields)?;
    // An empty name is a name the platform writes, not a reason to refuse the
    // record.  Every one of the 21 711 native forms of ERP УХ 3.2.12.6,
    // Документооборот КОРП 3.0.21.3, УТ 11.5.27.75 and БСП demo opens with an
    // `<AutoCommandBar>`; on 75 of them it reads `name="" id="-1"` (68 as an
    // empty element, 7 with child items).  Refusing those made the recursive
    // search walk past the form's own bar and either write nothing at all (19
    // ERP УХ forms) or promote a *nested* bar -- a list table's own
    // `СписокКоманднаяПанель` -- into the root position, name, id, `Autofill`
    // and all (42 forms).
    //
    // The refusal cannot be traded for a "named bars only" rule either way
    // round: over the same four trees an empty name occurs on the root bar and
    // nowhere else.  All 18 421 nested `<AutoCommandBar>` elements are named
    // and none carries id `-1`; all 75 empty-named ones are the root child and
    // all carry id `-1`.
    let (name, _) = parse_1c_quoted_string_with_len(fields.get(6)?.trim())?;
    Some(FormAutoCommandBar {
        id: id.to_string(),
        name,
        display_importance: schema.display_importance(fields),
        horizontal_align: schema.horizontal_align(),
        autofill: schema.autofill(),
        child_items: parse_form_child_item_pairs(
            fields,
            None,
            None,
            None,
            attribute_names_by_id,
            attribute_metadata_owners_by_id,
            table_name_by_id,
            standard_command_owner_name_by_id,
            command_source_owner_name_by_id,
            table_column_names_by_id,
            type_link_data_path_by_table_column,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            // The root command bar's own buttons name a target's standard
            // command exactly as any other button does, so they read the same
            // declaration table the child items read.
            metadata_command_facts_bindings,
            commands,
            &BTreeMap::new(),
            &BTreeSet::new(),
            object_refs,
        )
        .unwrap_or_default(),
    })
}

pub(super) fn parse_form_auto_command_bar_horizontal_align(field: &str) -> Option<&'static str> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.get(1).map(|value| value.trim())? {
        "1" => Some("Center"),
        "2" => Some("Right"),
        "3" => Some("Auto"),
        _ => None,
    }
}

pub(super) fn parse_form_context_menu_autofill(field: &str) -> Option<bool> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.get(1).map(|value| value.trim())? {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

/// The family of the form's main attribute, which is what brings the form its
/// write-cycle extension: `DocumentObject`, `CatalogObject`, `ConstantsSet`,
/// `ReportObject`, `SettingsComposer` and so on. `None` when the form declares
/// no main attribute at all, or declares one whose type is not exactly one
/// reference -- the two states in which no extension is declared.
pub(super) fn form_root_write_extension(attributes: &[FormAttribute]) -> Option<String> {
    let main = attributes
        .iter()
        .find(|attribute| attribute.main_attribute)?;
    let [ConstantValueType::Reference { reference }] = main.value_types.as_slice() else {
        return None;
    };
    let reference = reference
        .split_once(':')
        .map_or(reference.as_str(), |(_, tail)| tail);
    Some(
        reference
            .split_once('.')
            .map_or(reference, |(family, _)| family)
            .to_string(),
    )
}

/// What the form's own main attribute declares, as far as a name only a form
/// extension can carry needs to know.
///
/// `form_root_write_extension` answers `None` both for a form that declares no
/// main attribute and for one whose main attribute declares anything but a
/// single reference type; the event rule refuses in both states, and it is
/// measured in both. A button's standard-command name is only measured
/// refusing in the first, so the two have to be told apart here.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(super) enum FormMainAttributeExtension {
    /// Nothing has been read about the form's main attribute. Every name
    /// resolves exactly as it did before the fact existed.
    #[default]
    Unread,
    /// The form declares no main attribute at all, so it brings no extension.
    Absent,
    /// A main attribute is declared; the payload is the family of the single
    /// reference type it declares, or `None` when it declares anything else.
    Declared(Option<String>),
}

/// The form's main-attribute state, read off the same attribute collection
/// `form_root_write_extension` reads.
pub(super) fn form_main_attribute_extension(
    attributes: &[FormAttribute],
) -> FormMainAttributeExtension {
    if !attributes.iter().any(|attribute| attribute.main_attribute) {
        return FormMainAttributeExtension::Absent;
    }
    FormMainAttributeExtension::Declared(form_root_write_extension(attributes))
}

/// Whether the extension the form's main attribute brings owns the event this
/// identifier names.
///
/// An event identifier belongs to one form extension, and the platform writes
/// the identifier itself -- never a name -- when the form does not carry that
/// extension: the same "what it cannot name it writes physically" the
/// choice-parameter link and the `<TypeLink>` chain already follow.
///
/// Evidence, joining every root event record the export reads against the
/// native `<Form><Events>` of the same document over ERP УХ 3.2.12.6, БСП демо
/// 3.1.12.297 and Документооборот КОРП 3.0.21.3 (13 316 write-cycle records):
///
///   * a form that declares **no main attribute** names none of them -- 26
///     records, every one written as the raw identifier, against 0 named;
///   * a form whose main attribute is a **`DataProcessorObject`** names none of
///     them either -- 16 raw, 0 named. A data processor is not written, so the
///     write extension is not there to name;
///   * every other family names them and never leaves one raw: `CatalogObject`
///     5 904, `DocumentObject` 9 238, `InformationRegisterRecordManager` 1 764,
///     `TaskObject` 218, `BusinessProcessObject` 372, `ConstantsSet` 184,
///     `ChartOfCharacteristicTypesObject` 162, `ReportObject` 106,
///     `ExchangePlanObject` 96, `InformationRegisterRecordSet` 78,
///     `ChartOfCalculationTypesObject` 26, `ChartOfAccountsObject` 20,
///     `AccountingRegisterRecordSet` 12 and `SettingsComposer` 6;
///   * with the single exception of `9cc34712-…` (`BeforeWrite`) and
///     `bf0ac0e1-…` (`BeforeWriteAtServer`), which a `DocumentObject` form
///     never names -- 4 raw records each, 0 named -- because a document form
///     carries its own pair, `8a5894c9-…` and `8f42e083-…`, and the latter is
///     never seen on any other family (1 288 named, all `DocumentObject`).
///     ERP УХ `Documents/Лот/Forms/ФормаДокумента` carries both pairs against
///     the one handler `ПередЗаписью` and the platform names one and writes
///     the other out.
///
/// Only the states the platform was observed to decline in decline here: a
/// family this join has not seen carrying an identifier keeps naming it.
fn form_root_event_extension_owns(identifier: &str, write_extension: Option<&str>) -> bool {
    let Some(name) = form_event_name_from_identifier(identifier) else {
        return true;
    };
    if !matches!(
        name,
        "AfterWrite"
            | "AfterWriteAtServer"
            | "BeforeWrite"
            | "BeforeWriteAtServer"
            | "OnReadAtServer"
            | "OnWriteAtServer"
            | "OnUpdateUserSettingSetAtServer"
    ) {
        return true;
    }
    match write_extension {
        None | Some("DataProcessorObject") => false,
        Some("DocumentObject") => !matches!(
            identifier,
            "9cc34712-da5f-4faa-a653-343d2085fbe8" | "bf0ac0e1-bcbb-4dfe-8fc4-0b1923b461a6"
        ),
        Some(_) => true,
    }
}

pub(super) fn extract_form_body_events(
    fields: &[&str],
    write_extension: Option<&str>,
) -> Vec<FormBodyEvent> {
    let mut events = Vec::new();
    let mut seen = BTreeSet::new();
    collect_form_body_events(fields, write_extension, &mut events, &mut seen);
    events
}

pub(super) fn collect_form_body_events(
    fields: &[&str],
    write_extension: Option<&str>,
    events: &mut Vec<FormBodyEvent>,
    seen: &mut BTreeSet<(String, String)>,
) {
    for field in fields {
        let field = field.trim();
        if !field.starts_with('{') {
            continue;
        }
        let Some(nested) = split_1c_braced_fields(field, 0) else {
            continue;
        };
        if is_form_child_item_fields(&nested) {
            continue;
        }
        for event in parse_form_body_event_fields(&nested, write_extension) {
            if seen.insert((event.name.clone(), event.handler.clone())) {
                events.push(event);
            }
        }
        collect_form_body_events(&nested, write_extension, events, seen);
    }
}

pub(super) fn is_form_child_item_fields(fields: &[&str]) -> bool {
    let revision_fields = normalize_form_item_record_revision(fields);
    let raw_fields = revision_fields.as_deref().unwrap_or(fields);
    let Some(wrapper) = raw_fields.first().map(|value| value.trim()) else {
        return false;
    };
    // Same normalization the item reader applies, from the same source of
    // truth: a record whose conditional-`UserVisible` prefix shifts the
    // discriminator is still an item record, and answering otherwise here lets
    // `collect_form_body_events` descend into it and hoist its own events into
    // the form root. See `form_child_item_conditional_prefix_slot`.
    let normalized_fields =
        form_child_item_conditional_prefix_slot(wrapper, raw_fields).map(|prefix_slot| {
            raw_fields
                .iter()
                .enumerate()
                .filter_map(|(index, field)| (index != prefix_slot).then_some(*field))
                .collect::<Vec<_>>()
        });
    let fields = normalized_fields.as_deref().unwrap_or(raw_fields);
    form_child_item_tag(wrapper, fields).is_some()
}

pub(super) fn parse_form_body_event_fields(
    fields: &[&str],
    write_extension: Option<&str>,
) -> Vec<FormBodyEvent> {
    let mut events = Vec::new();
    for window in fields.windows(2) {
        if let Some(event) = parse_form_body_event_pair(window[0], window[1], write_extension) {
            events.push(event);
        }
    }
    events
}

pub(super) fn parse_form_body_event_pair(
    event_field: &str,
    handler_field: &str,
    write_extension: Option<&str>,
) -> Option<FormBodyEvent> {
    let event = parse_form_root_event_identifier(event_field, write_extension)?;
    let (handler, _) = parse_1c_quoted_string_with_len(handler_field.trim())?;
    let handler = handler.trim();
    if handler.is_empty() || !is_probable_form_event_handler(handler) {
        return None;
    }
    Some(FormBodyEvent {
        name: event,
        handler: handler.to_string(),
    })
}

pub(super) fn parse_form_event_identifier(field: &str) -> Option<String> {
    let field = field.trim();
    let identifier = parse_1c_quoted_string_with_len(field)
        .map(|(value, _)| value)
        .unwrap_or_else(|| field.to_string());
    let identifier = identifier.trim();
    form_event_name_from_identifier(identifier)
        .map(ToOwned::to_owned)
        .or_else(|| is_uuid_text(identifier).then(|| identifier.to_string()))
}

/// The same identifier read at the form root, where the extension the main
/// attribute brings decides whether the name may be spelled at all.
pub(super) fn parse_form_root_event_identifier(
    field: &str,
    write_extension: Option<&str>,
) -> Option<String> {
    let field = field.trim();
    let identifier = parse_1c_quoted_string_with_len(field)
        .map(|(value, _)| value)
        .unwrap_or_else(|| field.to_string());
    let identifier = identifier.trim();
    // The gate decides whether the *name* may be spelled, and the platform's
    // other spelling is the identifier itself. An identifier that is not a
    // uuid has no other spelling and no observation of the platform dropping
    // it, so it keeps its name.
    if !is_uuid_text(identifier) || form_root_event_extension_owns(identifier, write_extension) {
        if let Some(name) = form_event_name_from_identifier(identifier) {
            return Some(name.to_owned());
        }
    }
    is_uuid_text(identifier).then(|| identifier.to_string())
}

