pub(super) fn is_probable_form_event_handler(value: &str) -> bool {
    if value.len() > 512 || value.chars().any(char::is_whitespace) {
        return false;
    }
    value.chars().all(|ch| {
        ch == '_' || ch.is_alphanumeric() || ('А'..='я').contains(&ch) || ch == 'ё' || ch == 'Ё'
    })
}

#[allow(dead_code)]
pub(super) fn extract_form_item_assets(bytes: &[u8]) -> Vec<FormItemAsset> {
    let Ok(inflated) = inflate_raw_deflate(bytes) else {
        return Vec::new();
    };
    let Ok(text) = String::from_utf8(inflated) else {
        return Vec::new();
    };
    let text = text.trim_start_matches('\u{feff}');
    if !split_1c_braced_fields(text, 0)
        .and_then(|fields| fields.first().map(|value| value.trim() == "4"))
        .unwrap_or(false)
    {
        return Vec::new();
    }

    extract_form_item_assets_from_text(text)
}

pub(super) fn extract_form_item_assets_from_text(text: &str) -> Vec<FormItemAsset> {
    let mut assets = Vec::new();
    let mut offset = 0usize;
    let prefix = "{#base64:";
    while let Some(relative_start) = text[offset..].find(prefix) {
        let marker_start = offset + relative_start;
        let payload_start = marker_start + prefix.len();
        let Some(relative_end) = text[payload_start..].find('}') else {
            break;
        };
        let payload_end = payload_start + relative_end;
        if let Some(content) = decode_base64_mime(&text[payload_start..payload_end])
            && is_form_item_picture_content(&content)
            && let Some((item_name, property_name)) = form_item_picture_owner_at(text, marker_start)
        {
            assets.push(FormItemAsset {
                item_name,
                file_name: form_item_picture_file_name(property_name, &content),
                content,
            });
        }
        offset = payload_end + 1;
    }

    dedup_form_item_assets(assets)
}

pub(super) fn is_form_item_picture_content(bytes: &[u8]) -> bool {
    bytes.starts_with(b"\x89PNG\r\n\x1a\n")
        || bytes.starts_with(b"GIF87a")
        || bytes.starts_with(b"GIF89a")
        || bytes.starts_with(b"\x00\x00\x01\x00")
        || bytes.starts_with(b"\xff\xd8\xff")
        || bytes.starts_with(b"BM")
        || bytes.starts_with(b"PK\x03\x04")
        || is_svg_content(bytes)
}

pub(super) fn form_item_picture_owner_at(
    text: &str,
    marker_start: usize,
) -> Option<(String, &'static str)> {
    for (start, _) in text[..marker_start].match_indices('{').rev() {
        let Some(end) = scan_1c_braced_value(text, start) else {
            continue;
        };
        if end <= marker_start {
            continue;
        }
        let Some(split_fields) = split_1c_braced_fields(&text[start..end], 0) else {
            continue;
        };
        let revision_fields = normalize_form_item_record_revision(&split_fields);
        let raw_fields = revision_fields.as_deref().unwrap_or(&split_fields);
        let Some(wrapper) = raw_fields.first().map(|field| field.trim()) else {
            continue;
        };
        // The conditional `UserVisible` prefix shifts every member of the
        // record by one, and the asset scan has to see the same canonical
        // record the item reader sees -- otherwise the picture slot it samples
        // is the member in front of the picture. ERP УХ 3.2.12.6
        // `DataProcessors/ВыгрузкаЗагрузкаДанныхXML/Forms/Форма` table
        // `ДеревоМетаданных` is a prefixed wrapper-`55` record whose
        // `<RowsPicture>` element the item reader writes correctly from the
        // shifted slot, while the file beside it -- `RowsPicture.png` -- went
        // unwritten because this scan sampled the unshifted one.
        let prefixed_fields =
            form_child_item_conditional_prefix_slot(wrapper, raw_fields).map(|prefix_slot| {
                raw_fields
                    .iter()
                    .enumerate()
                    .filter_map(|(index, field)| (index != prefix_slot).then_some(*field))
                    .collect::<Vec<_>>()
            });
        let fields = prefixed_fields.as_deref().unwrap_or(raw_fields);
        if form_child_item_id(fields).is_none() {
            continue;
        }
        let Some(property_name) =
            form_item_picture_property_at(text, marker_start, wrapper, fields)
        else {
            continue;
        };
        if let Some(item_name) = parse_form_child_item_name(wrapper, fields) {
            return Some((item_name, property_name));
        }
    }
    None
}

pub(super) fn form_item_picture_property_at(
    text: &str,
    marker_start: usize,
    wrapper: &str,
    fields: &[&str],
) -> Option<&'static str> {
    let tag = form_child_item_tag(wrapper, fields)?;
    match (wrapper, tag) {
        ("12", "PictureDecoration") => {
            let options = fields
                .get(18)
                .and_then(|field| split_1c_braced_fields(field.trim(), 0))?;
            if options.first().map(|field| field.trim()) != Some("4") {
                return None;
            }
            form_item_picture_value_matches_marker(text, marker_start, options.get(1)?)
                .then_some("Picture")
        }
        ("31" | "34", "Button") if form_button_layout_is_extended(fields) => {
            let index = 25 + form_button_top_level_offset(fields);
            form_item_picture_value_matches_marker(text, marker_start, fields.get(index)?)
                .then_some("Picture")
        }
        ("55", "Table") => {
            form_item_picture_value_matches_marker(text, marker_start, fields.get(44)?)
                .then_some("RowsPicture")
        }
        // A page names its picture through the same option bag its other
        // properties come from, so the asset scan reads it through the very
        // schema the property reader uses rather than a slot of its own.
        ("22", "Page") => {
            let options = fields
                .get(FormPageSchema::OPTIONS_SLOT)
                .and_then(|field| split_1c_braced_fields(field.trim(), 0))?;
            let schema = FormPageSchema::from_raw_layout(
                wrapper,
                fields.len(),
                tag,
                fields.get(5).map(|field| field.trim()),
                &options,
            )?;
            form_item_picture_value_matches_marker(
                text,
                marker_start,
                options.get(schema.picture_option_slot())?,
            )
            .then_some("Picture")
        }
        ("37", "PictureField") => {
            let input_offset = form_input_field_top_level_offset(fields);
            if form_item_picture_value_matches_marker(
                text,
                marker_start,
                fields.get(29 + input_offset)?,
            ) {
                return Some("HeaderPicture");
            }
            let options = fields
                .get(39 + input_offset)
                .and_then(|field| split_1c_braced_fields(field.trim(), 0))?;
            if options.first().map(|field| field.trim()) != Some("10") {
                return None;
            }
            form_item_picture_value_matches_marker(text, marker_start, options.get(5)?)
                .then_some("ValuesPicture")
        }
        _ => None,
    }
}

pub(super) fn form_item_picture_value_matches_marker(
    text: &str,
    marker_start: usize,
    value: &str,
) -> bool {
    let Some(fields) = split_1c_braced_fields(value.trim(), 0) else {
        return false;
    };
    if fields.first().map(|field| field.trim()) != Some("4")
        || fields.get(1).map(|field| field.trim()) != Some("3")
    {
        return false;
    }
    let Some(payload_fields) = fields
        .get(7)
        .and_then(|field| split_1c_braced_fields(field.trim(), 0))
    else {
        return false;
    };
    let [marker] = payload_fields.as_slice() else {
        return false;
    };
    let marker = marker.trim();
    let Some(payload) = marker
        .strip_prefix("{#base64:")
        .and_then(|marker| marker.strip_suffix('}'))
    else {
        return false;
    };
    let Some(content) = decode_base64_mime(payload) else {
        return false;
    };
    if !is_form_item_picture_content(&content) {
        return false;
    }
    let Some(actual_start) = (marker.as_ptr() as usize).checked_sub(text.as_ptr() as usize) else {
        return false;
    };
    actual_start == marker_start
}

pub(super) fn form_item_picture_file_name(property_name: &str, content: &[u8]) -> String {
    let extension = ext_picture_file_name(content)
        .rsplit_once('.')
        .map(|(_, extension)| extension)
        .unwrap_or("bin");
    format!("{property_name}.{extension}")
}

fn extract_form_body_attributes_with_dcs_type_index(
    trailing: &[String],
    type_index: &BTreeMap<String, String>,
    dcs_type_index: &DcsTypeIndex,
    object_refs: &BTreeMap<String, String>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Vec<FormAttribute> {
    let Some(fields) = trailing
        .first()
        .and_then(|field| split_1c_braced_fields(field, 0))
    else {
        return Vec::new();
    };
    if fields.first().map(|field| field.trim()) != Some("4") {
        return Vec::new();
    }
    let attribute_count = fields
        .get(1)
        .and_then(|field| field.trim().parse::<usize>().ok())
        .unwrap_or(usize::MAX);
    fields
        .iter()
        .skip(2)
        .take(attribute_count)
        .filter_map(|field| {
            parse_form_attribute_with_dcs_type_index(
                field,
                type_index,
                dcs_type_index,
                object_refs,
                declarations,
            )
        })
        .collect()
}

/// Indent of the Form-wide `ConditionalAppearance` inside a decompiled
/// `Form.xml`: `Form`(1) / `Attributes`(2), so the wrapper itself sits one
/// level in from `<Attributes>`.
pub(super) const FORM_ATTRIBUTES_CONDITIONAL_APPEARANCE_INDENT: &str = "\t\t";

pub(super) fn extract_form_body_attributes_section(
    trailing: &[String],
    object_refs: &BTreeMap<String, String>,
) -> FormAttributesSection {
    let Some(text) = trailing.first() else {
        return FormAttributesSection::default();
    };
    let storage =
        match crate::module_blob::form_attributes_conditional_appearance_tail_storage_document(text)
        {
            Ok(Some(bytes)) => bytes,
            Ok(None) => {
                return FormAttributesSection {
                    conditional_appearance: None,
                };
            }
            // The physical layout itself did not read, so there is no storage
            // document to re-spell and the refusal stands on the raw tail.
            Err(_) => {
                return FormAttributesSection {
                    conditional_appearance: Some(
                        FormAttributesConditionalAppearance::OpaqueStorage {
                            bytes: text.as_bytes().to_vec(),
                            reason: "malformed Form Attributes conditional-appearance physical tail",
                        },
                    ),
                };
            }
        };
    // A cohort refusal says only that no enumerated shape describes the
    // document, never that the document cannot be spelled, so the lexical
    // writer is asked next and the typed refusal stands only if it too
    // cannot account for the bytes.
    let refused =
        |reason: &'static str| match transliterate_form_attributes_conditional_appearance_document(
            &storage,
            object_refs,
            FORM_ATTRIBUTES_CONDITIONAL_APPEARANCE_INDENT,
        ) {
            Some(xml) => FormAttributesConditionalAppearance::Transliterated(xml),
            None => FormAttributesConditionalAppearance::OpaqueStorage {
                bytes: storage.clone(),
                reason,
            },
        };
    let conditional_appearance =
        match crate::module_blob::parse_form_attributes_conditional_appearance_tail(text) {
            Ok(DcsChildParseOutcome::Typed(value)) => {
                Some(FormAttributesConditionalAppearance::Typed(value))
            }
            Ok(DcsChildParseOutcome::Unsupported(reason)) => Some(refused(reason)),
            Ok(DcsChildParseOutcome::Absent) => None,
            Err(_) => Some(refused(
                "Form Attributes conditional-appearance storage document is unreadable",
            )),
        };
    FormAttributesSection {
        conditional_appearance,
    }
}

pub(super) fn extract_form_body_attribute_save_field_bindings(
    trailing: &[String],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> BTreeMap<String, Vec<FormAttributeSaveFieldBinding>> {
    let Some(fields) = trailing
        .first()
        .and_then(|field| split_1c_braced_fields(field, 0))
    else {
        return BTreeMap::new();
    };
    if fields.first().map(|field| field.trim()) != Some("4") {
        return BTreeMap::new();
    }
    let attribute_count = fields
        .get(1)
        .and_then(|field| field.trim().parse::<usize>().ok())
        .unwrap_or(usize::MAX);
    let mut save_field_bindings = BTreeMap::new();
    for field in fields.iter().skip(2).take(attribute_count) {
        let Some(attribute) = parse_form_attribute(field, type_index, object_refs) else {
            continue;
        };
        let bindings = parse_form_attribute_save_field_bindings(Some(field));
        if !bindings.is_empty() {
            save_field_bindings.insert(attribute.name, bindings);
        }
    }
    save_field_bindings
}

pub(super) fn apply_form_body_attribute_additional_columns(
    attributes: &mut [FormAttribute],
    trailing: &[String],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    child_item_indexes: &FormChildItemIndexes,
) {
    let Some(fields) = trailing
        .first()
        .and_then(|field| split_1c_braced_fields(field, 0))
    else {
        return;
    };
    if fields.first().map(|field| field.trim()) != Some("4") {
        return;
    }
    let Some(attribute_count) = fields
        .get(1)
        .and_then(|field| field.trim().parse::<usize>().ok())
    else {
        return;
    };
    apply_form_attribute_additional_columns(
        attributes,
        &fields,
        2 + attribute_count,
        type_index,
        object_refs,
        child_item_indexes,
    );
}

pub(super) fn parse_form_attribute(
    field: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<FormAttribute> {
    parse_form_attribute_with_dcs_type_index(
        field,
        type_index,
        &DcsTypeIndex::new(),
        object_refs,
        None,
    )
}

#[cfg(test)]
pub(super) fn parse_form_attribute_with_declarations(
    field: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    declarations: &MetadataFieldDeclarationIndex,
) -> Option<FormAttribute> {
    parse_form_attribute_with_dcs_type_index(
        field,
        type_index,
        &DcsTypeIndex::new(),
        object_refs,
        Some(declarations),
    )
}

fn parse_form_attribute_with_dcs_type_index(
    field: &str,
    type_index: &BTreeMap<String, String>,
    dcs_type_index: &DcsTypeIndex,
    object_refs: &BTreeMap<String, String>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Option<FormAttribute> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|value| value.trim()) != Some("9") {
        return None;
    }
    let identity = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    let id = identity.first()?.trim();
    if id.is_empty() {
        return None;
    }
    let name = parse_1c_quoted_string_with_len(fields.get(3)?.trim())?.0;
    if name.is_empty() {
        return None;
    }
    let title = fields
        .get(4)
        .map(|field| parse_form_localized_strings(field))
        .unwrap_or_default();
    // An attribute's own pattern names a platform type exactly as one of its
    // columns does, so it is read through the same overlay: ERP УХ 3.2.12.6
    // `Catalogs/ТиповыеОперацииМеждународныйУчет/Forms/ФормаЭлемента` declares
    // six attributes as `{"Pattern",{"#",741ae838-…}}` and the platform writes
    // `<v8:Type>ent:AccountingRecordType</v8:Type>` for each, while the plain
    // index -- which carries only the configuration's own generated types --
    // could not name the identifier and refused the whole tuple.
    let parsed_value_types = fields
        .get(5)
        .and_then(|field| parse_form_attribute_column_type_pattern(field, type_index));
    let exact_single_type_uuid = fields
        .get(5)
        .and_then(|field| parse_form_exact_single_type_uuid(field));
    let explicit_empty_type = parsed_value_types
        .as_ref()
        .is_some_and(|value_types| value_types.is_empty());
    let value_types = parsed_value_types.unwrap_or_default();
    let columns = parse_form_attribute_columns(&fields, type_index, object_refs);
    // Slots 6 and 7 are the attribute's `<View>` and `<Edit>` permissions, in
    // the same tuple the command-interface visibility uses.  Both were read by
    // nobody, so the platform's blocks were simply never written.
    //
    // Evidence: UT 11.5.27.75, equality of sets over every attribute record the
    // export walks against every rights block the platform writes under
    // `Attributes/Attribute` anywhere in the configuration.  Slot 6 departs
    // from the default tuple on exactly 16 records and the native tree carries
    // exactly 16 `<View>` blocks, on those same attributes; slot 7 departs on
    // exactly 18 and there are exactly 18 `<Edit>` blocks, again the same ones.
    // Neither side has a member the other lacks.
    let view_rights = fields
        .get(6)
        .and_then(|field| parse_form_rights_setting(field, object_refs))
        .flatten();
    let edit_rights = fields
        .get(7)
        .and_then(|field| parse_form_rights_setting(field, object_refs))
        .flatten();
    let main_attribute = fields.get(10).map(|value| value.trim()) == Some("1");
    let saved_data = fields.get(11).map(|value| value.trim()) == Some("1");
    let fill_check =
        matches!(fields.get(12).map(|value| value.trim()), Some("1")).then_some("ShowError");
    let save_fields = parse_form_attribute_save_fields(
        fields.get(9).copied(),
        &name,
        exact_single_type_uuid.as_deref(),
    );
    // The attribute record declares its column count in slot 13 and stores the
    // columns themselves in the `count` slots that follow, so everything behind
    // the columns sits at a moving offset - the functional-option list is the
    // second slot after the last column, not a fixed slot 15.
    //
    // Reading slot 15 unconditionally only happens to be right for the
    // column-less attributes, where `count` is 0. For an attribute that does
    // declare columns, slot 15 is a *column* record, which carries no top-level
    // UUID, so the list came back empty and the platform's
    // `<FunctionalOptions>` block was simply never written.
    //
    // Evidence: UT 11.5.27.75, equality of sets over every attribute record the
    // export walks against every `Attributes/Attribute/FunctionalOptions` block
    // in the native tree - 905 native blocks, 888 of them column-less and
    // already emitted from slot 15, and the 17 remaining ones (plus 2 more
    // under embedded item-owned `Attributes`) all declare columns and hold
    // their list at `15 + count`. Every dumped record satisfies
    // `nfields == 16 + count`, so the slot is the record's last one.
    let column_count = fields
        .get(13)
        .and_then(|field| field.trim().parse::<usize>().ok())
        .unwrap_or(0);
    let functional_options = fields
        .get(15 + column_count)
        .map(|field| parse_form_reference_list(field, object_refs))
        .unwrap_or_default();
    let settings = fields.get(14).and_then(|field| {
        parse_form_dynamic_list_settings_with_dcs_type_index(field, object_refs, dcs_type_index)
    });
    let settings = settings.map(normalize_form_dynamic_list_settings);
    let spreadsheet_document_settings = fields.get(14).and_then(|field| {
        parse_form_spreadsheet_document_settings(field, &value_types, object_refs)
    });
    let design_time_settings = fields.get(14).and_then(|field| {
        parse_form_chart_settings_xml(field, &value_types, object_refs, 3)
            .or_else(|| parse_form_gantt_chart_settings_xml(field, &value_types, object_refs, 3))
            .or_else(|| parse_form_flowchart_settings_xml(field, &value_types, object_refs, 3))
            .or_else(|| parse_form_planner_settings_xml(field, &value_types, object_refs, 3))
    });
    let mut use_always = parse_form_attribute_direct_use_always(
        &name,
        fields.get(8).copied(),
        &columns,
        object_refs,
        exact_single_type_uuid
            .as_deref()
            .and_then(|uuid| type_index.get(uuid))
            .map(String::as_str),
        exact_single_type_uuid.as_deref(),
        declarations,
    );
    if let Some(dynamic_list_use_always) = fields.get(14).map(|field| {
        parse_form_attribute_use_always(&name, field, settings.as_ref(), object_refs, declarations)
    }) {
        let mut seen = use_always.iter().cloned().collect::<BTreeSet<_>>();
        for field_name in dynamic_list_use_always {
            if seen.insert(field_name.clone()) {
                use_always.push(field_name);
            }
        }
    }
    use_always.sort();
    let type_description_settings = fields
        .get(14)
        .and_then(|field| parse_form_type_description_settings(field, type_index));
    // The same resolvable-field universe `<UseAlways>` is measured against,
    // recorded per field-map id so a data path onto one of those fields can
    // carry the platform's own `~` marker.
    let unresolvable_field_item_ids = fields
        .get(14)
        .and_then(|field| {
            let settings_fields = split_1c_braced_fields(field.trim(), 0)?;
            let universe = form_dynamic_list_use_always_universe(
                settings.as_ref(),
                &settings_fields,
                object_refs,
                declarations,
            )?;
            let mut field_name_by_item_id =
                parse_form_dynamic_list_field_name_by_item_id(&settings_fields);
            if let Some(settings) = settings.as_ref() {
                for field in &settings.fields {
                    if let Some(item_id) = &field.item_id {
                        field_name_by_item_id
                            .entry(item_id.clone())
                            .or_insert_with(|| field.field.clone());
                    }
                }
            }
            let secondary_by_item_id =
                parse_form_dynamic_list_field_secondary_name_by_item_id(&settings_fields);
            let shadowed_item_ids =
                parse_form_dynamic_list_shadowed_field_item_ids(&settings_fields);
            Some(
                field_name_by_item_id
                    .into_iter()
                    .filter(|(item_id, field_name)| {
                        !form_dynamic_list_field_item_is_resolvable(
                            item_id,
                            field_name,
                            secondary_by_item_id.get(item_id).map(String::as_str),
                            &shadowed_item_ids,
                            &universe,
                        )
                    })
                    .map(|(item_id, _)| item_id)
                    .collect::<BTreeSet<String>>(),
            )
        })
        .unwrap_or_default();
    // The twin is remembered per field-map id, independently of whether the
    // field resolves: which of the two names gets written is the marker's
    // business, not the map's.
    let field_item_twins = fields
        .get(14)
        .and_then(|field| {
            let settings_fields = split_1c_braced_fields(field.trim(), 0)?;
            let field_name_by_item_id =
                parse_form_dynamic_list_field_name_by_item_id(&settings_fields);
            Some(
                parse_form_dynamic_list_field_secondary_name_by_item_id(&settings_fields)
                    .into_iter()
                    .filter(|(item_id, secondary)| {
                        field_name_by_item_id.get(item_id) != Some(secondary)
                    })
                    .collect::<BTreeMap<String, String>>(),
            )
        })
        .unwrap_or_default();
    Some(FormAttribute {
        id: id.to_string(),
        name,
        title,
        value_types,
        exact_single_type_uuid,
        explicit_empty_type,
        columns,
        additional_columns: Vec::new(),
        view_rights,
        edit_rights,
        main_attribute,
        saved_data,
        fill_check,
        save_fields,
        use_always,
        functional_options,
        settings,
        spreadsheet_document_settings,
        design_time_settings,
        type_description_settings,
        unresolvable_field_item_ids,
        field_item_twins,
    })
}

fn parse_form_exact_single_type_uuid(field: &str) -> Option<String> {
    let pattern = split_1c_braced_fields(field.trim(), 0)?;
    if pattern.len() != 2 || pattern.first()?.trim() != r#""Pattern""# {
        return None;
    }
    let value_type = split_1c_braced_fields(pattern.get(1)?.trim(), 0)?;
    if value_type.len() != 2 || value_type.first()?.trim() != r##""#""## {
        return None;
    }
    parse_non_zero_uuid(value_type.get(1)?.trim())
}

pub(super) fn parse_form_type_description_settings(
    field: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    fields.windows(2).find_map(|window| {
        parse_1c_quoted_string_with_len(window[0].trim())
            .filter(|(value, _)| value == "ElementType")
            .map(|_| {
                split_1c_braced_fields(window[1].trim(), 0)
                    .and_then(|value_fields| {
                        if value_fields.first().map(|field| field.trim()) == Some(r##""#""##) {
                            parse_form_type_pattern(value_fields.get(2)?.trim(), type_index)
                        } else {
                            parse_form_type_pattern(window[1].trim(), type_index)
                        }
                    })
                    .unwrap_or_default()
            })
    })
}

pub(super) fn normalize_form_dynamic_list_settings(
    mut settings: FormDynamicListSettings,
) -> FormDynamicListSettings {
    apply_implicit_form_dynamic_list_settings(&mut settings);
    settings
}

/// The three standard user settings of a dynamic list, and the identifier of
/// its grouping collection, as the platform materializes them.
///
/// Each of `Filter`, `Order` and the conditional-appearance property is a
/// separate storage document with three physical states, and the platform
/// answers each state the same way wherever it occurs:
///
/// * property ABSENT -> the platform materializes the standard setting and
///   writes it: `<dcsset:viewMode>Normal` plus the fixed identifier the build
///   assigns to that setting;
/// * property PRESENT and empty -> the platform writes nothing for it;
/// * property PRESENT with content -> the content is written.
///
/// Evidence: UT 11.5.27.75, all 1 947 native `<Settings xsi:type="DynamicList">`
/// blocks in the corpus, read as the physical state of the packed bag against
/// the platform's own bytes -- 5 841 property instances, 5 070 absent, 366
/// present-with-content the typed cohort refuses, 225 present-with-content it
/// accepts, and 180 present-and-empty. The standard setting is written for
/// every one of the 5 070 absences, spread over 1 850 blocks, and for none of
/// the 180 empties, spread over 68. The two states never mix inside one bag --
/// of the 19 observed `(Filter, Order, Appearance)` state triples not one pairs
/// an absent property with an empty one -- so the container stays empty
/// (`<ListSettings/>`) exactly for the 49 bags whose three properties are all
/// empty, which is what the previous rule already produced for them.
///
/// The identifiers are not per-object values: `dfcece9d-…`, `88619765-…`,
/// `b75fecce-…` and `911b6018-…` are one build-wide constant per setting,
/// carried by the packed storage documents themselves (see the base64 bodies in
/// `module_blob`), and the repetition is what identifies them as the standard
/// settings rather than saved ones.
///
/// `AutoSaveUserSettings` does not gate any of this. It was previously read as
/// the switch that turns the materialization on, and that is measurably wrong:
/// 13 of the 16 blocks whose bag stores it as false carry at least one absent
/// property, and the platform materializes the standard setting in every one of
/// them; the remaining 3 have nothing to materialize because all three of their
/// properties are physically present.
pub(super) fn apply_implicit_form_dynamic_list_settings(settings: &mut FormDynamicListSettings) {
    let list_settings = &mut settings.list_settings;
    let has_any_list_settings = list_settings.filter.is_some()
        || list_settings.order.is_some()
        || list_settings.conditional_appearance.is_some();
    if list_settings.filter.is_none() {
        list_settings.filter = Some(FormListSettingsFilter::Typed(
            default_form_list_settings_filter(),
        ));
    }
    if list_settings.order.is_none() {
        list_settings.order = Some(FormListSettingsOrder::Typed(
            default_form_list_settings_order(),
        ));
    }
    if list_settings.conditional_appearance.is_none() {
        list_settings.conditional_appearance = Some(FormListSettingsConditionalAppearance::Typed(
            platform_default_form_list_settings_conditional_appearance()
                .expect("bundled conditional-appearance default is valid"),
        ));
    }
    if !has_any_list_settings
        && list_settings.items_view_mode.is_none()
        && list_settings.items_user_setting_id.is_none()
    {
        list_settings.items_view_mode = Some("Normal".to_string());
        list_settings.items_user_setting_id =
            Some("911b6018-f537-43e8-a417-da56b22f9aec".to_string());
        return;
    }
    if list_settings.items_user_setting_id.is_none() {
        list_settings.items_user_setting_id =
            Some("911b6018-f537-43e8-a417-da56b22f9aec".to_string());
        if list_settings.items_view_mode.is_none() {
            list_settings.items_view_mode = Some("Normal".to_string());
        }
    }
}

fn default_form_list_settings_order() -> DcsOrder {
    platform_default_form_list_settings_order()
        .expect("bundled platform-authenticated metadata-only Form order is valid")
}

fn default_form_list_settings_filter() -> DcsFilter {
    platform_default_form_list_settings_filter()
        .expect("bundled platform-authenticated metadata-only Form filter is valid")
}

pub(super) fn parse_form_attribute_save_fields(
    field: Option<&str>,
    attribute_name: &str,
    value_type_uuid: Option<&str>,
) -> Vec<String> {
    let Some(entries) = field.and_then(parse_form_attribute_save_entries) else {
        return Vec::new();
    };
    let mut parsed = Vec::new();
    for entry in &entries {
        match entry {
            FormAttributeSaveEntry::SelfValue => parsed.push(attribute_name.to_string()),
            FormAttributeSaveEntry::ValueTypeProperty(path) => {
                if let Some(property) =
                    value_type_uuid.and_then(|uuid| form_value_type_property_name(uuid, path))
                {
                    parsed.push(format!("{attribute_name}.{property}"));
                }
            }
            FormAttributeSaveEntry::Binding(_) => {}
        }
    }
    parsed
}

/// Properties of the platform value types that a saved-field entry addresses by
/// a walk of indexes. Every row below is read off platform output:
/// `v8:StandardPeriod` index 0 alone yields `Variant`, and indexes 0/1/2
/// together yield `EndDate`/`StartDate`/`Variant`; `v8:StandardBeginningDate`
/// index 0 yields `Variant`; `dcsset:SettingsComposer` index 0 yields
/// `Settings` and the two-step walk 0/1 yields `Settings.Filter`. Walks with no
/// observation stay unresolved rather than being guessed.
///
/// The two-step walk is what the ten native `<Field>...Settings.Filter</Field>`
/// entries of UT 11.5.27.75 spell, and it is the only multi-step walk the
/// configuration contains; reading only the first step used to drop the entry,
/// which dropped the whole `<Save>` block with it.
pub(super) fn form_value_type_property_name(uuid: &str, path: &[i64]) -> Option<&'static str> {
    match (uuid, path) {
        // v8:StandardPeriod
        ("2fdc88ec-7c9b-43cd-8ba5-873f043bdd88", [0]) => Some("Variant"),
        ("2fdc88ec-7c9b-43cd-8ba5-873f043bdd88", [1]) => Some("StartDate"),
        ("2fdc88ec-7c9b-43cd-8ba5-873f043bdd88", [2]) => Some("EndDate"),
        // v8:StandardBeginningDate. `1` is the type's own date, read off the
        // platform: the seed `seeds/ada-probe` gives one form attribute per
        // probed member name, and 8.3.27.2214 stores `SBD1.Variant` as
        // `{1,{0}}` and `SBD2.Date` as `{1,{1}}`.
        ("0387f3a2-7df5-4804-948b-4580a51e4a15", [0]) => Some("Variant"),
        ("0387f3a2-7df5-4804-948b-4580a51e4a15", [1]) => Some("Date"),
        // dcsset:SettingsComposer. Indexes 1 and 2 are named by the one
        // composer attribute of UT 11.5.27.75 whose use-always list spells
        // them, `CommonForms/ФормаВыбораДоступногоПоля`: it holds `{1}` and
        // `{2}`, and the platform writes `FixedSettings` and `UserSettings`.
        //
        // That list carries both indexes at once and the platform sorts the
        // block, so it could not tell the two apart; read in sorted order it
        // put `FixedSettings` on `1`, and that is the wrong way round. A seed
        // separates them: a data processor whose form holds one settings
        // composer per probed name, each with a single-entry `<UseAlways>`,
        // imported and saved by 8.3.27.2214 (`seeds/ada-composer2`), stores
        // `B7.FixedSettings` as `{1,{2}}` and `B8.UserSettings` as `{1,{1}}`.
        // The composer's own member table read the same numbering all along --
        // `form_settings_composer_member` has `1` as `UserSettings` -- so the
        // swap also removes a contradiction between the two tables. Both
        // indexes occur only side by side in all eight stand corpora (7 blocks,
        // never one without the other), which is why the sorted output never
        // showed the error.
        ("cab0d12b-3c88-4993-8edc-8c3827cadc7d", [0]) => Some("Settings"),
        ("cab0d12b-3c88-4993-8edc-8c3827cadc7d", [0, 1]) => Some("Settings.Filter"),
        ("cab0d12b-3c88-4993-8edc-8c3827cadc7d", [1]) => Some("UserSettings"),
        ("cab0d12b-3c88-4993-8edc-8c3827cadc7d", [2]) => Some("FixedSettings"),
        // v8:ValueListType. Solved from the platform's own answer over the 11
        // value-list attributes of UT 11.5.27.75 whose use-always list is a
        // pure index list: `{3}` alone yields `Picture`, `{-1,3}` yields
        // `Picture`+`ValueType`, `{-1,1,3}` adds `Presentation` and
        // `{-1,1,2,3}` adds `Check`, which fixes all four indexes with no
        // freedom left. The four rows account for every native `Picture` (11),
        // `Presentation` (8), `ValueType` (10) and `Check` (1) field in the
        // configuration, so no other value type reaches these codes.
        //
        // The type-blind table this replaces had `-1` and `3` the other way
        // round; the swap stayed invisible because a list that carries both
        // writes the same sorted pair either way.
        //
        // `0` is the list's own value, the fifth member. It is not deducible
        // from UT: no list there names it. The seed `seeds/ada-probe` names it
        // alone -- 8.3.27.2214 stores `VL1.Value` as `{1,{0}}` -- and the same
        // seed re-reads the four rows above off the platform one at a time,
        // `{1,{-1}}`, `{1,{1}}`, `{1,{2}}`, `{1,{3}}`, which confirms the UT
        // deduction member by member instead of as a sorted set.
        ("4772b3b4-f4a3-49c0-a1a5-8cb5961511a3", [-1]) => Some("ValueType"),
        ("4772b3b4-f4a3-49c0-a1a5-8cb5961511a3", [0]) => Some("Value"),
        ("4772b3b4-f4a3-49c0-a1a5-8cb5961511a3", [1]) => Some("Presentation"),
        ("4772b3b4-f4a3-49c0-a1a5-8cb5961511a3", [2]) => Some("Check"),
        ("4772b3b4-f4a3-49c0-a1a5-8cb5961511a3", [3]) => Some("Picture"),
        _ => None,
    }
}

/// The standard property a use-always code names on an attribute typed as a
/// whole metadata object.
///
/// Code `-8` is the only such code UT 11.5.27.75 spells, and it reaches exactly
/// two value-type kinds: `cfg:DocumentObject` on 330 attributes, every one of
/// which the platform writes `RegisterRecords` for, and `cfg:CatalogObject` on
/// one, which the platform writes `Ref` for. A catalogue has no register
/// records, so the same code cannot mean the same property on both.
pub(super) fn form_object_standard_property_name(
    value_type: &str,
    code: i64,
) -> Option<&'static str> {
    let kind = value_type
        .strip_prefix("cfg:")
        .unwrap_or(value_type)
        .split_once('.')?
        .0;
    match (kind, code) {
        ("CatalogObject", -8) => Some("Ref"),
        ("DocumentObject", -8) => Some("RegisterRecords"),
        _ => None,
    }
}

fn parse_form_attribute_save_entries(field: &str) -> Option<Vec<FormAttributeSaveEntry>> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|value| value.trim()) != Some("0") {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    if fields.len() != 2 + count {
        return None;
    }
    fields
        .iter()
        .skip(2)
        .map(|field| {
            let entry = split_1c_braced_fields(field.trim(), 0)?;
            // An entry declares how many components its walk has and then spells
            // that many of them; matching arity 1 alone refused the two-component
            // walks the platform writes, and refusing one entry threw the whole
            // list away.
            let components = entry.first()?.trim().parse::<usize>().ok()?;
            if entry.len() != 1 + components {
                return None;
            }
            if components == 0 {
                return Some(FormAttributeSaveEntry::SelfValue);
            }
            // A bare index is a property of the attribute's own value type; a
            // `{0,<uuid>}` pair is a binding into the form item tree. Both used
            // to collapse into the same string binding key, which is why
            // value-type properties were resolved against unrelated form items.
            let indexes = entry[1..]
                .iter()
                .map(|component| {
                    let fields = split_1c_braced_fields(component.trim(), 0)?;
                    let [index] = fields.as_slice() else {
                        return None;
                    };
                    // Only an unsigned index is a value-type property walk; a
                    // negative code is a form-item binding and must stay one.
                    index.trim().parse::<usize>().ok().map(|index| index as i64)
                })
                .collect::<Option<Vec<_>>>();
            if let Some(indexes) = indexes {
                return Some(FormAttributeSaveEntry::ValueTypeProperty(indexes));
            }
            // The walk opens with the member it binds and may spell further
            // members after it, each a bare code. Reading only the
            // one-component shape refused the longer walks outright, and
            // because the whole list is read as one, refusing a single entry
            // threw every other entry of that attribute away with it.
            //
            // Evidence: UT 11.5.27.75,
            // `DataProcessors/ПлатежныйКалендарь/Forms/Форма`. Its `Объект`
            // attribute declares 26 saved fields, 25 of them one-component
            // and the 26th `{3,{0,<uuid>},{0},{1}}`, which the platform writes
            // `Объект.КомпоновщикОтбор.Settings.Filter`. The one refusal cost
            // the whole `<Save>` block.
            let [_, payload, rest @ ..] = entry.as_slice() else {
                return None;
            };
            let payload_fields = split_1c_braced_fields(payload.trim(), 0)?;
            let key = parse_form_binding_key(payload.trim())?;
            let metadata_uuid = match payload_fields.as_slice() {
                [kind, uuid] if kind.trim() == "0" => parse_non_zero_uuid(uuid.trim()),
                _ => None,
            };
            let members = rest
                .iter()
                .map(|component| {
                    let fields = split_1c_braced_fields(component.trim(), 0)?;
                    let [code] = fields.as_slice() else {
                        return None;
                    };
                    let code = code.trim();
                    code.parse::<i64>().ok().map(|_| code.to_string())
                })
                .collect::<Option<Vec<_>>>()?;
            Some(FormAttributeSaveEntry::Binding(
                FormAttributeSaveFieldBinding {
                    key,
                    metadata_uuid,
                    members,
                    physical_members: form_physical_chain_spelling(&entry[1..]),
                },
            ))
        })
        .collect()
}

pub(super) fn parse_form_attribute_save_field_bindings(
    field: Option<&str>,
) -> Vec<FormAttributeSaveFieldBinding> {
    let Some(fields) = field.and_then(|value| split_1c_braced_fields(value.trim(), 0)) else {
        return Vec::new();
    };
    let Some(entries) = fields
        .get(9)
        .and_then(|value| parse_form_attribute_save_entries(value))
    else {
        return Vec::new();
    };
    entries
        .into_iter()
        .filter_map(|entry| match entry {
            FormAttributeSaveEntry::SelfValue | FormAttributeSaveEntry::ValueTypeProperty(_) => {
                None
            }
            FormAttributeSaveEntry::Binding(binding) => Some(binding),
        })
        .collect()
}

pub(super) fn apply_form_attribute_save_field_bindings(
    attributes: &mut [FormAttribute],
    save_field_bindings: &BTreeMap<String, Vec<FormAttributeSaveFieldBinding>>,
    data_path_by_binding_key: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) {
    for attribute in attributes {
        let metadata_owner = form_attribute_metadata_owner(attribute);
        let mut seen = attribute
            .save_fields
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        if let Some(bindings) = save_field_bindings.get(&attribute.name) {
            for binding in bindings {
                let data_path = if binding.members.is_empty() {
                    data_path_by_binding_key
                        .get(&binding.key)
                        .cloned()
                        .or_else(|| {
                            resolve_form_attribute_save_metadata_path(
                                &metadata_owner,
                                binding.metadata_uuid.as_deref()?,
                                object_refs,
                            )
                        })
                } else {
                    // A walk that spells members past the one it binds names a
                    // settings composer and walks it with the same member
                    // table an item's bound slot is walked with. The binding
                    // key covers only the first component, so it answers a
                    // shorter path than the entry states and is not asked.
                    let base = resolve_form_attribute_save_metadata_path(
                        &metadata_owner,
                        binding.metadata_uuid.as_deref().unwrap_or_default(),
                        object_refs,
                    );
                    base.zip(form_settings_composer_member_walk(&binding.members))
                        .map(|(base, tail)| format!("{base}{tail}"))
                };
                // A saved field whose metadata reference this configuration
                // cannot name is not a malformed entry: the platform writes it
                // out physically -- the owner the entry belongs to, then the
                // entry's own segments, in the same
                // `<owner>/<member>:<member>` spelling an unnameable
                // choice-parameter link and an unnameable `<TypeLink>` are
                // written in. Answering nothing dropped the entry, and an
                // attribute whose every entry was such a reference lost its
                // whole `<Save>` block --
                // `DataProcessors/ПечатьЭтикетокИЦенниковБПО/Forms/Форма` of
                // Документооборот КОРП 3.0.21.3 is exactly that.
                //
                // Corpus: 35 such fields over the eight stand trees, 4 in that
                // Документооборот form and 31 across ten ERP УХ 3.2.12.6
                // forms, every one of them `1/0:<uuid>` against an entry
                // `{1,{0,<uuid>}}` on an attribute whose id is `1`.
                // `DataProcessors/ИмпортОбъектовИзExcel/Forms/Форма` of ERP УХ
                // holds both outcomes in one block: seven entries of that one
                // shape, six of whose uuids are attributes of
                // `DataProcessor.ИмпортОбъектовИзExcel` and are written
                // `Объект.<name>`, and `3db98de4-…`, which the configuration
                // names nowhere and which is written `1/0:3db98de4-…`. The
                // bytes are identical either way, so only the resolution
                // decides the spelling.
                //
                // Only a metadata terminal falls back: that is the terminal
                // the corpus writes physically, and no other terminal has ever
                // been observed unresolved here.
                let data_path = data_path.or_else(|| {
                    let members = binding.physical_members.as_deref()?;
                    binding
                        .metadata_uuid
                        .is_some()
                        .then(|| format!("{}/{members}", attribute.id))
                });
                if let Some(data_path) = data_path
                    && seen.insert(data_path.clone())
                {
                    attribute.save_fields.push(data_path);
                }
            }
        }
        attribute.save_fields.sort();
        attribute.save_fields.dedup();
    }
}

fn resolve_form_attribute_save_metadata_path(
    attribute: &FormAttributeMetadataOwner,
    metadata_uuid: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let reference = object_refs.get(metadata_uuid)?;
    let (owner_base, relative_path) = form_metadata_data_path_route(reference)?;
    form_attribute_matches_metadata_owner(attribute, &owner_base)
        .then(|| format!("{}.{}", attribute.name, relative_path))
}

pub(super) fn parse_form_attribute_columns(
    fields: &[&str],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Vec<FormAttributeColumn> {
    let Some(count) = fields
        .get(13)
        .and_then(|field| field.trim().parse::<usize>().ok())
    else {
        return Vec::new();
    };
    fields
        .iter()
        .skip(14)
        .take(count)
        .filter_map(|field| parse_form_attribute_column(field, type_index, object_refs))
        .collect()
}

pub(super) fn apply_form_attribute_additional_columns(
    attributes: &mut [FormAttribute],
    fields: &[&str],
    start_index: usize,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    child_item_indexes: &FormChildItemIndexes,
) {
    let Some(group_count) = fields
        .get(start_index)
        .and_then(|field| field.trim().parse::<usize>().ok())
    else {
        return;
    };
    let mut section_keys: BTreeMap<String, Vec<Option<String>>> = BTreeMap::new();
    for field in fields.iter().skip(start_index + 1).take(group_count) {
        let Some(group) = parse_form_attribute_additional_columns_group(
            field,
            attributes,
            type_index,
            object_refs,
            child_item_indexes,
        ) else {
            continue;
        };
        if let Some(attribute) = attributes
            .iter_mut()
            .find(|attribute| attribute.id == group.attribute_id)
        {
            section_keys
                .entry(group.attribute_id.clone())
                .or_default()
                .push(group.tabular_section_uuid.clone());
            attribute
                .additional_columns
                .push(FormAttributeAdditionalColumns {
                    table: group.table,
                    columns: group.columns,
                });
        }
    }
    order_form_attribute_additional_columns(attributes, &section_keys);
}

/// The platform does not write an attribute's `<AdditionalColumns>` groups in
/// the order the record lists them: it writes them ordered by the uuid of the
/// tabular section each group names.
///
/// Census over all eight stand corpora of every `<Columns>` block holding more
/// than one group whose tables are tabular sections of the attribute's own
/// metadata object — 342 blocks, of which 330 belong to files that already
/// match byte for byte: the platform's order is ascending by tabular-section
/// uuid in every one, with no counter-example. Two rival readings were
/// refuted by the same census: the owner's declaration order (forward or
/// reversed) is contradicted by 93 already-matching blocks, and "self-closed
/// groups first" by 45.
///
/// The record order agrees with that key almost everywhere, which is why only
/// `uh` `Catalogs/ПакетыДанных/Forms/ФормаЭлемента` moved: it lists
/// `ПоказателиОтчета`, `ИзмеренияИсточников`, `ИсточникиДанных` and the
/// platform writes the last two first. Groups bound to anything but a tabular
/// section of the attribute's own object carry no such key and are left in
/// record order, so an attribute that mixes the two is not reordered at all.
fn order_form_attribute_additional_columns(
    attributes: &mut [FormAttribute],
    section_keys: &BTreeMap<String, Vec<Option<String>>>,
) {
    for attribute in attributes.iter_mut() {
        let Some(keys) = section_keys.get(&attribute.id) else {
            continue;
        };
        if keys.len() != attribute.additional_columns.len() || keys.iter().any(|key| key.is_none())
        {
            continue;
        }
        let mut ordered = keys
            .iter()
            .map(|key| key.clone().unwrap_or_default())
            .zip(std::mem::take(&mut attribute.additional_columns))
            .collect::<Vec<_>>();
        ordered.sort_by(|left, right| left.0.cmp(&right.0));
        attribute.additional_columns = ordered.into_iter().map(|(_, group)| group).collect();
    }
}

pub(super) struct ParsedFormAttributeAdditionalColumnsGroup {
    pub(super) attribute_id: String,
    pub(super) table: String,
    pub(super) columns: Vec<FormAttributeColumn>,
    /// The uuid of the tabular section this group's table names, when the
    /// table is a tabular section of the attribute's own metadata object.
    /// It is the key the platform orders the groups by; see
    /// `order_form_attribute_additional_columns`.
    pub(super) tabular_section_uuid: Option<String>,
}

pub(super) fn parse_form_attribute_additional_columns_group(
    field: &str,
    attributes: &[FormAttribute],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    child_item_indexes: &FormChildItemIndexes,
) -> Option<ParsedFormAttributeAdditionalColumnsGroup> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let target = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    let owner = split_1c_braced_fields(target.get(1)?.trim(), 0)?;
    let binding = match target.get(2) {
        Some(binding) => split_1c_braced_fields(binding.trim(), 0)?,
        None => Vec::new(),
    };
    let schema = FormAttributeAdditionalColumnsGroupSchema::from_raw_layout(
        &fields, &target, &owner, &binding,
    )?;
    let attribute_id = owner.first()?.trim().to_string();
    let attribute = attributes
        .iter()
        .find(|attribute| attribute.id == attribute_id)?;
    let columns = fields
        .iter()
        .skip(3)
        .take(schema.column_count())
        .map(|field| parse_form_attribute_column(field, type_index, object_refs))
        .collect::<Option<Vec<_>>>()?;
    let mut tabular_section_uuid = None;
    let (table, nested_binding_start) = match schema.binding_kind() {
        FormAttributeAdditionalColumnsBindingKind::Attribute => (attribute.name.clone(), 2),
        FormAttributeAdditionalColumnsBindingKind::Numeric => {
            let column_id = binding.first()?.trim();
            let table = attribute
                .columns
                .iter()
                .find(|column| column.id == column_id)
                .map(|column| format!("{}.{}", attribute.name, column.name))?;
            (table, 3)
        }
        // A negative marker names a standard tabular section of the
        // attribute's own family, the same member and the same marker a bound
        // slot's table segment names. Evidence: ERP УХ
        // `ChartsOfAccounts/Хозрасчетный/Forms/ФормаСчета`, whose sole
        // additional-columns group is `{0,{2,{1},{-12}},0}` against the
        // `Объект` attribute of exact type `cfg:ChartOfAccountsObject.…`, and
        // the platform writes
        // `<AdditionalColumns table="Объект.ExtDimensionTypes"/>`; the group
        // used to be refused whole, because a declared column id is
        // non-negative and nothing else read the slot.
        FormAttributeAdditionalColumnsBindingKind::StandardMember => {
            let reference = form_attribute_exact_single_type_reference(attribute)?;
            let marker = binding.first()?.trim();
            if let Some((_, section_name, _)) =
                form_standard_tabular_section_for_type_reference(reference, marker)
            {
                (format!("{}.{section_name}", attribute.name), 3)
            } else {
                // The marker names no standard tabular section but a standard
                // *collection* of the attribute's own family, and the segment
                // after it names the member of that collection the columns
                // belong to. The one collection the corpus shows here is a
                // document object's `RegisterRecords`, whose member is a
                // register named by uuid — the same three segments
                // `resolve_form_document_register_records_data_path` already
                // reads for a bound slot. Evidence: ERP УХ 3.2.12.6
                // `Documents/ОперацияБух`, `ОперацияМСФО` and
                // `ОперацияМеждународный`, whose form bodies carry
                // `{3,{1},{-8},{0,<register uuid>}}` against the `Объект`
                // attribute and whose platform XML writes
                // `<AdditionalColumns table="Объект.RegisterRecords.<register>">`.
                // Nothing read the segment, so both groups of each form were
                // dropped and every item bound to one of their columns spelled
                // its own name instead of the column's.
                let collection =
                    form_object_standard_property_name(reference, marker.parse::<i64>().ok()?)?;
                if collection != "RegisterRecords" {
                    return None;
                }
                let member = split_1c_braced_fields(target.get(3)?.trim(), 0)?;
                let [prefix, register_uuid] = member.as_slice() else {
                    return None;
                };
                if prefix.trim() != "0" {
                    return None;
                }
                let register_uuid = parse_non_zero_uuid(register_uuid.trim())?;
                let register_reference = object_refs.get(&register_uuid)?;
                let (register_family, register_name) = register_reference.split_once('.')?;
                if register_name.contains('.')
                    || !form_register_family_holds_document_records(register_family)
                {
                    return None;
                }
                (
                    format!("{}.{collection}.{register_name}", attribute.name),
                    4,
                )
            }
        }
        FormAttributeAdditionalColumnsBindingKind::MetadataReference => {
            let type_id = binding.get(1)?.trim();
            let table = resolve_form_attribute_additional_columns_metadata_table_path(
                &attribute_id,
                type_id,
                target.get(2)?.trim(),
                attributes,
                object_refs,
                child_item_indexes,
            )?;
            tabular_section_uuid = parse_non_zero_uuid(type_id).filter(|uuid| {
                object_refs.get(uuid).is_some_and(|reference| {
                    matches!(
                        reference.split('.').collect::<Vec<_>>().as_slice(),
                        [_, _, "TabularSection", section] if !section.is_empty()
                    )
                })
            });
            (table, 3)
        }
    };
    let table = resolve_form_attribute_nested_additional_columns_table_path(
        attribute,
        table,
        target.get(nested_binding_start..)?,
    )?;
    // Only a group whose table is still the whole tabular section keeps the
    // ordering key: a nested segment addresses a column inside it, and the
    // census that established the key covers no such group.
    if nested_binding_start < target.len() {
        tabular_section_uuid = None;
    }
    Some(ParsedFormAttributeAdditionalColumnsGroup {
        attribute_id,
        table,
        columns,
        tabular_section_uuid,
    })
}

const FORM_VALUE_TABLE_COLUMN_BINDING_UUID: &str = "5bdad865-f2c5-434b-8041-ba4aad3b6687";

fn resolve_form_attribute_nested_additional_columns_table_path(
    attribute: &FormAttribute,
    mut table: String,
    bindings: &[&str],
) -> Option<String> {
    for binding in bindings {
        let binding = split_1c_braced_fields(binding.trim(), 0)?;
        let [column_id, marker] = binding.as_slice() else {
            return None;
        };
        if column_id.trim().parse::<u64>().is_err()
            || !marker
                .trim()
                .eq_ignore_ascii_case(FORM_VALUE_TABLE_COLUMN_BINDING_UUID)
        {
            return None;
        }
        let column_name =
            resolve_form_attribute_additional_column_name(attribute, &table, column_id.trim())?;
        table.push('.');
        table.push_str(column_name);
    }
    Some(table)
}

fn resolve_form_attribute_additional_column_name<'a>(
    attribute: &'a FormAttribute,
    table: &str,
    column_id: &str,
) -> Option<&'a str> {
    form_attribute_additional_column_name_in(&attribute.additional_columns, table, column_id)
}

/// The declared name of one additional column of `table`, or nothing when the
/// id is unknown there or two groups of the same table spell it differently.
fn form_attribute_additional_column_name_in<'a>(
    groups: &'a [FormAttributeAdditionalColumns],
    table: &str,
    column_id: &str,
) -> Option<&'a str> {
    let mut name = None;
    for candidate in groups
        .iter()
        .filter(|additional| additional.table == table)
        .flat_map(|additional| additional.columns.iter())
        .filter(|column| column.id == column_id)
        .map(|column| column.name.as_str())
    {
        if name.is_some_and(|name| name != candidate) {
            return None;
        }
        name = Some(candidate);
    }
    name
}

fn resolve_form_attribute_additional_columns_metadata_table_path(
    attribute_id: &str,
    type_id: &str,
    binding: &str,
    attributes: &[FormAttribute],
    object_refs: &BTreeMap<String, String>,
    child_item_indexes: &FormChildItemIndexes,
) -> Option<String> {
    let type_id = parse_non_zero_uuid(type_id)?;
    if let Some(reference) = object_refs.get(&type_id) {
        let (owner_base, relative_path) =
            form_attribute_additional_columns_metadata_route(reference)?;
        let attribute_owners = form_attribute_metadata_owners_by_id(attributes);
        let attribute = attribute_owners.get(attribute_id)?;
        return form_attribute_matches_metadata_owner(attribute, &owner_base)
            .then(|| format!("{}.{}", attribute.name, relative_path));
    }

    let binding_key = parse_form_binding_key(binding)?;
    let scoped_key = FormBoundTableKey {
        attribute_id: attribute_id.to_string(),
        table_key: binding_key.clone(),
    };
    match child_item_indexes
        .owner_scoped_bindings
        .table_paths
        .get(&scoped_key)
    {
        Some(Some(table)) => return Some(table.clone()),
        Some(None) => return None,
        None => {}
    }
    None
}

fn form_attribute_additional_columns_metadata_route(reference: &str) -> Option<(String, String)> {
    let route = reference.split('.').collect::<Vec<_>>();
    let (owner_kind, owner_name, relative_path) = match route.as_slice() {
        [owner_kind, owner_name, "TabularSection", table] if !table.is_empty() => {
            (*owner_kind, *owner_name, (*table).to_string())
        }
        [owner_kind, owner_name, "Attribute", attribute] if !attribute.is_empty() => {
            (*owner_kind, *owner_name, (*attribute).to_string())
        }
        _ => return None,
    };
    if owner_kind.is_empty() || owner_name.is_empty() {
        return None;
    }
    Some((format!("{owner_kind}.{owner_name}"), relative_path))
}

pub(super) fn parse_form_attribute_column(
    field: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<FormAttributeColumn> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    FormAttributeColumnSchema::from_raw_layout(&fields)?;
    let id = fields.get(1)?.trim();
    if id.is_empty() {
        return None;
    }
    let name = parse_1c_quoted_string_with_len(fields.get(3)?.trim())?.0;
    if name.is_empty() {
        return None;
    }
    let parsed_value_types = fields
        .get(5)
        .and_then(|field| parse_form_attribute_column_type_pattern(field, type_index));
    Some(FormAttributeColumn {
        id: id.to_string(),
        name,
        title: fields
            .get(4)
            .map(|field| parse_form_localized_strings(field))
            .unwrap_or_default(),
        value_types: parsed_value_types.clone().unwrap_or_default(),
        explicit_empty_type: parsed_value_types
            .as_ref()
            .is_some_and(|value_types| value_types.is_empty()),
        // A column keeps its `<View>` and `<Edit>` permissions in the same two
        // slots an attribute does, in the same tuple.
        //
        // Evidence: UT 11.5.27.75, equality of sets over all 53 251 column
        // records the export walks against every rights block the platform
        // writes under `Attributes/Attribute/Columns/Column` in the whole
        // configuration -- slot 6 departs from the default tuple on exactly one
        // record and there is exactly one native `<View>` block, on that same
        // column; slot 7 departs on exactly three and there are exactly three
        // native `<Edit>` blocks, on those same three columns.
        view_rights: fields
            .get(6)
            .and_then(|field| parse_form_rights_setting(field, object_refs))
            .flatten(),
        edit_rights: fields
            .get(7)
            .and_then(|field| parse_form_rights_setting(field, object_refs))
            .flatten(),
        functional_options: fields
            .get(8)
            .map(|field| parse_form_reference_list(field, object_refs))
            .unwrap_or_default(),
        // Slot 9 is a total function of the platform's column-level
        // `<FillCheck>` over all 53 251 column records the export walks in
        // UT 11.5.27.75: it holds `1` on exactly the records of the 9 native
        // columns that write `<FillCheck>ShowError</FillCheck>` and `0` on
        // every other record, with no record holding `1` without the element
        // and none writing the element without the `1`. Every column record has
        // exactly 10 slots, so this is its last one. `ShowError` is the only
        // value observed; any other encoding stays unread rather than guessed.
        fill_check: matches!(fields.get(9).map(|value| value.trim()), Some("1"))
            .then_some("ShowError"),
    })
}

pub(super) fn parse_form_attribute_column_type_pattern(
    field: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    let trimmed = field.trim();
    if let Some(value_types) = parse_form_type_pattern(trimmed, type_index) {
        return Some(value_types);
    }
    // A column pattern may name a platform type that neither the
    // configuration-wide index nor the shared builtin table carries. Those are
    // resolved by overlaying the column-scoped table onto the index and running
    // the one pattern grammar again - not by recognising a pattern shape.
    //
    // Matching a shape is what this fallback used to do, and it admitted exactly
    // one element. That rejected the very layout it exists to serve: the
    // `ЛевоеЗначение` column of `CommonForms/ФормаНастроекОтчета` pairs
    // `dcscor:Field` with the platform `Null` type, two elements, and the
    // platform writes both. Going through the shared grammar also keeps the
    // elements the shared tables already resolve resolving exactly as before -
    // the overlay only adds identifiers the index does not define, so it can
    // never shadow an entry, and it is built only when the pattern actually
    // names one, so the common path is untouched.
    let overlay = form_attribute_column_type_index_overlay(trimmed, type_index)?;
    parse_form_type_pattern(trimmed, &overlay)
}

/// `type_index` plus the column-scoped platform references the pattern names and
/// the index lacks, or `None` when the pattern names none of them.
fn form_attribute_column_type_index_overlay(
    field: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<BTreeMap<String, String>> {
    let pattern = split_1c_braced_fields(field, 0)?;
    if pattern.first()?.trim() != r#""Pattern""# {
        return None;
    }
    let mut additions = BTreeMap::new();
    for element in pattern.iter().skip(1) {
        let Some(type_id) = metadata_type_pattern_field_type_id(element) else {
            continue;
        };
        if type_id.is_empty() || type_index.contains_key(&type_id) {
            continue;
        }
        if let Some(reference) = form_attribute_column_builtin_type_reference(&type_id) {
            additions.insert(type_id, reference.to_string());
        }
    }
    if additions.is_empty() {
        return None;
    }
    let mut overlay = type_index.clone();
    overlay.extend(additions);
    Some(overlay)
}

#[cfg(test)]
pub(super) fn parse_form_dynamic_list_settings(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FormDynamicListSettings> {
    parse_form_dynamic_list_settings_with_dcs_type_index(field, object_refs, &DcsTypeIndex::new())
}

fn parse_form_dynamic_list_settings_with_dcs_type_index(
    field: &str,
    object_refs: &BTreeMap<String, String>,
    dcs_type_index: &DcsTypeIndex,
) -> Option<FormDynamicListSettings> {
    let settings_fields = split_1c_braced_fields(field.trim(), 0)?;
    let mut auto_save_user_settings = None;
    let mut auto_fill_available_fields = None;
    let mut get_invisible_field_presentations = None;
    let mut key_type = None;
    let mut key_fields = Vec::new();
    let mut manual_query = false;
    let mut manual_query_explicit = false;
    let mut dynamic_data_read = false;
    let mut dynamic_data_read_explicit = false;
    let mut query_text = None;
    let mut main_table = None;
    let mut main_table_category = None;
    let mut explicit_fields = Vec::new();
    let mut fields = Vec::new();
    let mut server_state_xml = None;
    let mut server_state_envelope = None;
    let mut list_settings = FormListSettings::default();
    let conditional_appearance_property = bundled_dcs_conditional_appearance_policy()
        .ok()?
        .storage_property_name()
        .to_owned();
    for window in settings_fields.windows(2) {
        let key = parse_1c_quoted_string_with_len(window[0].trim())
            .map(|(value, _)| value)
            .unwrap_or_default();
        match key.as_str() {
            "QueryText" => query_text = parse_form_setting_string(window[1]),
            "MainTable" => main_table = parse_form_main_table_ref(window[1], object_refs),
            "MainTableCategory" => main_table_category = parse_form_setting_number(window[1]),
            "Field" => {
                let parsed_fields = parse_form_dynamic_list_fields(window[1]);
                explicit_fields.extend(parsed_fields.clone());
                fields.extend(parsed_fields);
            }
            "AutoSaveUserSettings" => auto_save_user_settings = parse_form_setting_bool(window[1]),
            "AutoFillAvailableFields" => {
                auto_fill_available_fields = parse_form_setting_bool(window[1])
            }
            "GetInvisibleFieldPresentations" => {
                get_invisible_field_presentations = parse_form_setting_bool(window[1])
            }
            "KeyType" => key_type = parse_form_dynamic_list_key_type(window[1]),
            "KeyFields" => key_fields = parse_form_dynamic_list_key_fields(window[1]),
            "ManualQuery" => {
                manual_query_explicit = true;
                manual_query = parse_form_setting_bool(window[1]).unwrap_or(false);
            }
            "DynamicalDataSelection" => {
                dynamic_data_read_explicit = true;
                dynamic_data_read = !parse_form_setting_bool(window[1]).unwrap_or(true)
            }
            "Filter" => {
                list_settings.filter = parse_form_list_settings_filter(window[1], object_refs)
            }
            "Order" => list_settings.order = parse_form_list_settings_order(window[1], object_refs),
            property if property == conditional_appearance_property => {
                list_settings.conditional_appearance =
                    parse_form_list_settings_conditional_appearance(window[1], object_refs)
            }
            "ItemsViewMode" => list_settings.items_view_mode = parse_form_setting_string(window[1]),
            "ItemsUserSettingID" => {
                list_settings.items_user_setting_id = parse_form_setting_string(window[1])
            }
            "GroupSelectedSettingId" => {
                list_settings.items_user_setting_id = parse_form_setting_string(window[1])
            }
            "Group" => {
                list_settings.group_items =
                    parse_form_list_settings_group_items(window[1], object_refs)
            }
            "DataParameters" => {
                list_settings.data_parameters =
                    parse_form_list_settings_data_parameters(window[1], object_refs)
            }
            // `GroupSelectedSettingViewMode` is the record that decides
            // `dcsset:itemsViewMode` whenever the bag carries the group family;
            // the identifier next to it decides nothing about it.
            //
            // Evidence: UT 11.5.27.75, the 1 517 forms whose single bag record
            // pairs with a single native `<ListSettings>`. All 34 records with
            // `{"N",0}` sit in a block the platform closes with
            // `<dcsset:itemsViewMode>Normal`, all 19 with `{"N",1}` in a block it
            // closes without one -- and that holds whether
            // `GroupSelectedSettingId` is empty (23 / 15) or not (11 / 4), so the
            // identifier is not the discriminator the inference below took it for.
            // Over the whole tree the record occurs 124 times, `{"N",0}` 48 and
            // `{"N",1}` 76, no other value, and no form carries fewer native
            // `itemsViewMode` elements than it has `{"N",0}` records.
            "GroupSelectedSettingViewMode" => {
                if let Some(value) = parse_form_group_selected_setting_view_mode(window[1]) {
                    list_settings.items_view_mode = Some(value.to_string());
                }
            }
            "ServerState" => {
                server_state_xml = parse_form_server_state_xml_with_indexes(
                    window[1],
                    dcs_type_index,
                    object_refs,
                );
                server_state_envelope = parse_form_server_state_envelope(window[1]);
            }
            _ => {}
        }
    }
    main_table = normalize_form_main_table_category(main_table, main_table_category.as_deref());
    fields.extend(parse_form_dynamic_list_field_map_items(&settings_fields));
    dedupe_form_dynamic_list_fields(&mut fields);
    if query_text.is_none()
        && main_table.is_none()
        && fields.is_empty()
        && !manual_query
        && !dynamic_data_read
        && server_state_xml.is_none()
        && list_settings.filter.is_none()
        && list_settings.order.is_none()
        && list_settings.conditional_appearance.is_none()
        && list_settings.items_view_mode.is_none()
        && list_settings.items_user_setting_id.is_none()
    {
        return None;
    }
    Some(FormDynamicListSettings {
        auto_fill_available_fields,
        get_invisible_field_presentations,
        key_type,
        key_fields,
        auto_save_user_settings,
        manual_query,
        manual_query_explicit,
        dynamic_data_read,
        dynamic_data_read_explicit,
        query_text,
        main_table,
        explicit_fields,
        fields,
        server_state_xml,
        server_state_envelope,
        list_settings,
    })
}

pub(super) fn parse_form_dynamic_list_fields(field: &str) -> Vec<FormDynamicListField> {
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return Vec::new();
    };
    let mut parsed = Vec::new();
    if fields.first().map(|value| value.trim()) == Some("0")
        && fields
            .get(1)
            .and_then(|value| value.trim().parse::<usize>().ok())
            .is_some()
    {
        for item in fields.iter().skip(2) {
            if let Some(parsed_item) = parse_form_dynamic_list_field_item(item) {
                parsed.push(parsed_item);
            }
        }
        return parsed;
    }
    for pair in fields.chunks_exact(2) {
        if let Some(parsed_item) = parse_form_dynamic_list_field_pair(pair[0], pair[1]) {
            parsed.push(parsed_item);
        }
    }
    parsed
}

pub(super) fn parse_form_dynamic_list_field_item(field: &str) -> Option<FormDynamicListField> {
    let item_fields = split_1c_braced_fields(field.trim(), 0)?;
    if item_fields.len() < 2 {
        return None;
    }
    parse_form_dynamic_list_field_pair(item_fields[0], item_fields[1])
}

pub(super) fn parse_form_dynamic_list_field_pair(
    data_path_field: &str,
    field_field: &str,
) -> Option<FormDynamicListField> {
    let data_path = parse_form_setting_scalar_string(data_path_field)?;
    let field = parse_form_setting_scalar_string(field_field)?;
    if data_path.is_empty() || field.is_empty() {
        return None;
    }
    Some(FormDynamicListField {
        item_id: None,
        data_path,
        field,
    })
}

pub(super) fn parse_form_setting_scalar_string(field: &str) -> Option<String> {
    parse_1c_quoted_string_with_len(field.trim())
        .map(|(value, _)| value)
        .or_else(|| parse_form_setting_string(field))
}

pub(super) fn parse_form_dynamic_list_field_map_items(
    settings_fields: &[&str],
) -> Vec<FormDynamicListField> {
    let mut field_name_by_suffix = BTreeMap::<String, String>::new();
    let mut item_id_by_suffix = BTreeMap::<String, String>::new();
    // Non-overlapping pairs only: `windows(2)` used to slide by one, so each
    // "FiledsMapItemId{N}"/"FiledsMapItemName{N}" key literal was tried
    // against BOTH of its neighbors, not just its real pair partner. When a
    // reversed-order layout put the key right after its own value (the
    // correct pairing) *and* right before the next suffix's own value (a
    // structurally-valid-looking but spurious pairing), the spurious call
    // could silently overwrite the correct entry with the next suffix's
    // data — observed as a one-suffix shift with the last value duplicated.
    // `chunks_exact(2)` keeps each key literal paired with exactly its own
    // neighbor, in whichever of the two supported orderings this layout
    // uses, with no cross-pair contamination.
    for pair in settings_fields.chunks_exact(2) {
        collect_form_dynamic_list_field_map_item(
            pair[0],
            pair[1],
            &mut field_name_by_suffix,
            &mut item_id_by_suffix,
        );
        collect_form_dynamic_list_field_map_item(
            pair[1],
            pair[0],
            &mut field_name_by_suffix,
            &mut item_id_by_suffix,
        );
    }
    field_name_by_suffix
        .into_iter()
        .filter_map(|(suffix, field_name)| {
            item_id_by_suffix
                .get(&suffix)
                .cloned()
                .map(|item_id| FormDynamicListField {
                    item_id: Some(item_id),
                    data_path: field_name.clone(),
                    field: field_name,
                })
        })
        .collect()
}

pub(super) fn parse_form_attribute_use_always(
    attribute_name: &str,
    settings_field: &str,
    settings: Option<&FormDynamicListSettings>,
    object_refs: &BTreeMap<String, String>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Vec<String> {
    let Some(settings_fields) = split_1c_braced_fields(settings_field.trim(), 0) else {
        return Vec::new();
    };
    let required_item_ids = parse_form_dynamic_list_required_item_ids(&settings_fields);
    if required_item_ids.is_empty() {
        return Vec::new();
    }
    let mut field_name_by_item_id = parse_form_dynamic_list_field_name_by_item_id(&settings_fields);
    if let Some(settings) = settings {
        for field in &settings.fields {
            if let Some(item_id) = &field.item_id {
                field_name_by_item_id
                    .entry(item_id.clone())
                    .or_insert_with(|| field.field.clone());
            }
        }
    }
    let secondary_by_item_id =
        parse_form_dynamic_list_field_secondary_name_by_item_id(&settings_fields);
    let shadowed_item_ids = parse_form_dynamic_list_shadowed_field_item_ids(&settings_fields);
    let main_table = settings.and_then(|settings| settings.main_table.as_deref());
    let universe = form_dynamic_list_use_always_universe(
        settings,
        &settings_fields,
        object_refs,
        declarations,
    );
    let mut parsed = Vec::new();
    let mut seen = BTreeSet::<String>::new();
    for item_id in required_item_ids {
        let Some(field_name) = form_dynamic_list_use_always_field_name(
            attribute_name,
            &item_id,
            &field_name_by_item_id,
            &secondary_by_item_id,
            &shadowed_item_ids,
            main_table,
            universe.as_ref(),
        ) else {
            continue;
        };
        if seen.insert(field_name.clone()) {
            parsed.push(field_name);
        }
    }
    parsed
}

pub(super) fn parse_form_dynamic_list_field_name_by_item_id(
    settings_fields: &[&str],
) -> BTreeMap<String, String> {
    parse_form_dynamic_list_field_map_items(settings_fields)
        .into_iter()
        .filter_map(|field| field.item_id.map(|item_id| (item_id, field.field)))
        .collect()
}

/// The localized twin the field map records beside a field's own name.
///
/// A standard attribute of the list's source is remembered under its English
/// name, with the Russian spelling kept next to it as
/// `FieldsMapItemSecondaryName{N}` — `Code`/`Код`, `Ref`/`Ссылка`. Both name
/// the same field of the list, so a remembered field is resolvable when either
/// spelling is; and when neither is, the platform writes the pair out in full,
/// `~<attr>.<name>~<attr>.<twin>`.
///
/// Evidence: the whole stand. Of the 5 359 required-field records that carry a
/// twin, 5 358 are written without the marker — the single exception is
/// `Documents/Лот/Forms/ФормаСписка`, whose remembered `Owner`/`Владелец` pair
/// names a standard attribute no document has. Nine records in ERP УХ 3.2.12.6
/// write the doubled spelling, and every one of them is a remembered pair whose
/// two names are both unresolvable.
pub(super) fn parse_form_dynamic_list_field_secondary_name_by_item_id(
    settings_fields: &[&str],
) -> BTreeMap<String, String> {
    let mut item_id_by_suffix = BTreeMap::<String, String>::new();
    let mut secondary_by_suffix = BTreeMap::<String, String>::new();
    let mut collect = |key_field: &str, value_field: &str| {
        let key = parse_1c_quoted_string_with_len(key_field.trim())
            .map(|(value, _)| value)
            .unwrap_or_default();
        if let Some(suffix) = key
            .strip_prefix("FiledsMapItemSecondaryName")
            .or_else(|| key.strip_prefix("FieldsMapItemSecondaryName"))
        {
            if let Some(name) = parse_form_setting_scalar_string(value_field)
                && !name.is_empty()
            {
                secondary_by_suffix.insert(suffix.to_string(), name);
            }
            return;
        }
        if let Some(suffix) = key
            .strip_prefix("FiledsMapItemId")
            .or_else(|| key.strip_prefix("FieldsMapItemId"))
            && let Some(item_id) = parse_form_setting_number(value_field)
        {
            item_id_by_suffix.insert(suffix.to_string(), item_id);
        }
    };
    for pair in settings_fields.chunks_exact(2) {
        collect(pair[0], pair[1]);
        collect(pair[1], pair[0]);
    }
    secondary_by_suffix
        .into_iter()
        .filter_map(|(suffix, secondary)| {
            item_id_by_suffix
                .get(&suffix)
                .map(|item_id| (item_id.clone(), secondary))
        })
        .collect()
}

pub(super) fn parse_form_attribute_direct_use_always(
    attribute_name: &str,
    field: Option<&str>,
    columns: &[FormAttributeColumn],
    object_refs: &BTreeMap<String, String>,
    value_type: Option<&str>,
    value_type_uuid: Option<&str>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Vec<String> {
    let Some(fields) = field.and_then(|value| split_1c_braced_fields(value.trim(), 0)) else {
        return Vec::new();
    };
    if fields.first().map(|value| value.trim()) != Some("0") {
        return Vec::new();
    }
    let Some(count) = fields
        .get(1)
        .and_then(|value| value.trim().parse::<usize>().ok())
    else {
        return Vec::new();
    };
    if value_type_uuid == Some(CONSTANTS_SET_TYPE_UUID) {
        if let Some(constants) = declarations.and_then(|declarations| {
            form_constants_set_use_always(
                attribute_name,
                fields.iter().skip(2).take(count).copied(),
                object_refs,
                declarations,
            )
        }) {
            return constants;
        }
    }
    let mut parsed = Vec::new();
    let mut seen = BTreeSet::<String>::new();
    for entry in fields.iter().skip(2).take(count) {
        let Some(entry_fields) = split_1c_braced_fields(entry.trim(), 0) else {
            continue;
        };
        // An entry declares how many components its path has and then spells
        // that many of them. Demanding exactly one refused every path that
        // steps through a tabular section - `{2,{0,<section>},{0,<column>}}` -
        // and the platform writes 42 of those in UT 11.5.27.75, every one of
        // them silently dropped here.
        let Some(components) = entry_fields
            .first()
            .and_then(|value| value.trim().parse::<usize>().ok())
        else {
            continue;
        };
        if components == 0 || entry_fields.len() != 1 + components {
            continue;
        }
        let parts = entry_fields[1..]
            .iter()
            .map(|component| split_1c_braced_fields(component.trim(), 0))
            .collect::<Option<Vec<_>>>();
        let Some(parts) = parts else {
            continue;
        };
        // A settings composer walks its own member tables end to end: its
        // members name each other, and naming each component against the
        // composer's head alone gets every step past the first wrong.
        let joined = if value_type_uuid == Some(DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID) {
            form_settings_composer_use_always_path(&parts)
        } else if let Some(path) = form_object_settings_composer_use_always_path(&parts) {
            Some(path)
        } else {
            parts
                .iter()
                .map(|value_fields| {
                    form_attribute_use_always_segment_name(
                        value_fields,
                        columns,
                        object_refs,
                        value_type,
                        value_type_uuid,
                    )
                })
                .collect::<Option<Vec<_>>>()
                .map(|segments| segments.join("."))
        };
        let Some(joined) = joined else {
            continue;
        };
        let field_name = format!("{attribute_name}.{joined}");
        if seen.insert(field_name.clone()) {
            parsed.push(field_name);
        }
    }
    parsed
}

/// The `<UseAlways>` of a `cfg:ConstantsSet` attribute, read as a delta against
/// what each constant declares rather than as the set itself.
///
/// A constant whose own record declares it always used is written when the
/// form's record leaves it out and left out when the record names it; every
/// other constant is written exactly where the record names it. A constant
/// whose declared type is `v8:ValueStorage` is never written at all. See
/// [`MetadataConstantDeclaration`] for the join both readings are measured
/// against.
///
/// `None` when the record holds anything but one-component constant references
/// -- the shape the delta is measured on -- or when the declaration index
/// carries no constants, in which case the caller writes the record verbatim as
/// before.
fn form_constants_set_use_always<'a>(
    attribute_name: &str,
    entries: impl Iterator<Item = &'a str>,
    object_refs: &BTreeMap<String, String>,
    declarations: &MetadataFieldDeclarationIndex,
) -> Option<Vec<String>> {
    let mut recorded = BTreeSet::<String>::new();
    for entry in entries {
        let entry_fields = split_1c_braced_fields(entry.trim(), 0)?;
        if entry_fields.len() != 2 || entry_fields.first()?.trim() != "1" {
            return None;
        }
        let component = split_1c_braced_fields(entry_fields.get(1)?.trim(), 0)?;
        if component.len() != 2 || component.first()?.trim() != "0" {
            return None;
        }
        recorded.insert(parse_uuid_field(component.get(1)?.trim())?);
    }
    let mut effective = recorded.clone();
    let mut declared_any = false;
    for uuid in declarations.always_used_constants() {
        declared_any = true;
        if !effective.remove(uuid) {
            effective.insert(uuid.to_string());
        }
    }
    if !declared_any && recorded.is_empty() {
        return None;
    }
    let mut named = Vec::new();
    for uuid in effective {
        let declared = declarations.constant(&uuid)?;
        if declared.value_storage {
            continue;
        }
        let reference = object_refs.get(&uuid)?;
        let name = reference.rsplit_once('.')?.1;
        named.push(format!("{attribute_name}.{name}"));
    }
    named.sort();
    Some(named)
}

/// One entry of a `dcsset:SettingsComposer` attribute's `<UseAlways>`, walked
/// through the same member tables an item's bound chain walks.
///
/// The two id spaces are the same one: ERP УХ 3.2.12.6 spells
/// `{3,{0},{1},{10002}}` for `Settings.Filter.LeftValue` on five composer
/// attributes and `{3,{0},{4},{10005}}` for
/// `Settings.ConditionalAppearance.UseArea` on a sixth, and `Settings` member
/// `1` is `Filter` and `4` is `ConditionalAppearance` in the chain table, read
/// off UT 11.5.27.75. Resolving each component on its own instead named the
/// second one against the composer's own top-level table, so every one of
/// those six entries was dropped and the block never written.
///
/// A head other than `Settings` is a member of the composer itself and is read
/// off the composer's own value-type table. That table and the chain table
/// agree on every id -- both now say `1` is `UserSettings` and `2` is
/// `FixedSettings`, as the seed `seeds/ada-composer2` reads them off the
/// platform one at a time. A path that steps past a member the table gives no
/// collection for refuses -- the entry is dropped, exactly as before.
fn form_settings_composer_use_always_path(components: &[Vec<&str>]) -> Option<String> {
    let head = components.first()?.first()?.trim();
    let mut owner = match head {
        "0" => FormSettingsComposerType::Settings,
        _ => {
            return (components.len() == 1)
                .then(|| {
                    form_value_type_property_name(
                        DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID,
                        &[head.parse::<i64>().ok()?],
                    )
                    .map(str::to_string)
                })
                .flatten();
        }
    };
    let mut names = vec![
        form_value_type_property_name(DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID, &[0])?
            .to_string(),
    ];
    for component in &components[1..] {
        if component.len() != 1 {
            return None;
        }
        let (name, next) = form_settings_composer_member(owner, component.first()?.trim())?;
        names.push(name.to_string());
        match next {
            Some(next) => owner = next,
            None => {
                if names.len() != components.len() {
                    return None;
                }
            }
        }
    }
    Some(names.join("."))
}

/// One entry of a use-always list whose attribute is the object that *owns* a
/// settings composer rather than the composer itself.
///
/// The entry names the object's built-in composer member by the same uuid a
/// bound field slot names it by, and then walks the composer's own member
/// tables. Resolving each component against the attribute's own value type
/// instead -- a report object -- named the member for nothing and dropped the
/// entry, and with it the whole block.
///
/// Evidence, ERP УХ 3.2.12.6
/// `Reports/ОборотноСальдоваяВедомостьПоСчету/Forms/ФормаОтчета`: attribute
/// `Отчет`, declared `cfg:ReportObject.ОборотноСальдоваяВедомостьПоСчету`,
/// holds the two entries `{2,{0,b9754f01-…},{1}}` and `{2,{0,b9754f01-…},{2}}`,
/// and the platform writes `Отчет.SettingsComposer.FixedSettings` and
/// `Отчет.SettingsComposer.UserSettings`. `b9754f01-…` is the member uuid the
/// bound-slot route already reads as `SettingsComposer`, and `1`/`2` are the
/// composer's own members.
fn form_object_settings_composer_use_always_path(components: &[Vec<&str>]) -> Option<String> {
    let (head, rest) = components.split_first()?;
    let [marker, uuid] = head.as_slice() else {
        return None;
    };
    if marker.trim() != "0"
        || !uuid
            .trim()
            .eq_ignore_ascii_case(FORM_OBJECT_SETTINGS_COMPOSER_MEMBER_UUID)
    {
        return None;
    }
    let mut owner = Some(FormSettingsComposerType::SettingsComposer);
    let mut path = String::from("SettingsComposer");
    for component in rest {
        let [member] = component.as_slice() else {
            return None;
        };
        let (name, next) = form_settings_composer_member(owner?, member.trim())?;
        path.push('.');
        path.push_str(name);
        owner = next;
    }
    Some(path)
}

/// One step of a use-always path: either a metadata object the configuration
/// names - a tabular section, an attribute, a column - or a code that stands
/// for a property the metadata does not carry a reference for.
pub(super) fn form_attribute_use_always_segment_name(
    value_fields: &[&str],
    columns: &[FormAttributeColumn],
    object_refs: &BTreeMap<String, String>,
    value_type: Option<&str>,
    value_type_uuid: Option<&str>,
) -> Option<String> {
    // `{0,<uuid>}` names a metadata object; a bare `{0}` is the code zero, and
    // reading it as a truncated pair refused it before it ever reached the
    // type's own property table. Evidence: the seed `seeds/ada-probe` stores
    // `SBD1.Variant`, `VL1.Value` and `SP1.Variant` as `{1,{0}}`, and the
    // platform writes all three.
    if value_fields.len() == 2 && value_fields.first().map(|value| value.trim()) == Some("0") {
        let uuid = parse_uuid_field(value_fields.get(1)?.trim())?;
        let reference = object_refs.get(&uuid)?;
        return Some(reference.rsplit_once('.')?.1.to_string());
    }
    let code = value_fields.first()?.trim();
    if let Some(column) = columns.iter().find(|column| column.id == code) {
        return Some(column.name.clone());
    }
    // A code names a property of the attribute's own value type, so the type
    // answers it where the configuration has spelled the answer out; the
    // type-blind table below is what is left for the types it has not.
    if let Ok(index) = code.parse::<i64>() {
        if let Some(property) =
            value_type_uuid.and_then(|uuid| form_value_type_property_name(uuid, &[index]))
        {
            return Some(property.to_string());
        }
        if let Some(property) =
            value_type.and_then(|value_type| form_object_standard_property_name(value_type, index))
        {
            return Some(property.to_string());
        }
    }
    // The standard attributes and standard tabular sections of the generated
    // owner type the attribute is declared as, read from the same per-family
    // tables a bound field slot reads. The two id spaces are the same one: the
    // seed `seeds/ada-probe` stores `Date` as `{1,{-3}}`, `DeletionMark`
    // `{-4}`, `Number` `{-2}`, `Posted` `{-7}` and `Ref` `{-5}` for an
    // attribute declared `cfg:DocumentObject.…`, which is
    // `DOCUMENT_STANDARD_ATTRIBUTES` marker for marker -- a table built from
    // the 1 395 bound slots of UT 11.5.27.75, never from a use-always list.
    //
    // It sits ahead of the type-blind table below and behind the two rows above
    // it: `-8` is `RegisterRecords` on a document object and `Ref` on a catalog
    // object, and neither family's own table claims that marker.
    if let Some(property) = value_type
        .and_then(|value_type| form_standard_attribute_name_for_type_reference(value_type, code))
    {
        return Some(property.to_string());
    }
    match code {
        "-10" => Some("Predefined".to_string()),
        "-8" => Some("RegisterRecords".to_string()),
        "-1" => Some("Picture".to_string()),
        "1" => Some("Presentation".to_string()),
        "3" => Some("ValueType".to_string()),
        _ => None,
    }
}

/// Field-map ids whose remembered name an earlier entry of the same map already
/// remembers.
///
/// The list's available-field collection holds one entry per name: the first
/// remembered id binds to it, and a later id remembering the same name binds to
/// nothing, so the platform writes that one marked -- beside the plain spelling
/// the first id produced, in the same `<UseAlways>` block.
///
/// Evidence: ERP УХ 3.2.12.6 `Catalogs/Лоты/Forms/ФормаСписка` and
/// `Documents/Лот/Forms/ФормаСписка`, the only two dynamic lists on the whole
/// stand whose field map remembers one name under two ids that are both
/// required. Both remember `Ref`/`Ссылка` under ids 534 and 756 and
/// `DeletionMark`/`ПометкаУдаления` under 645 and 807, and both native
/// `<UseAlways>` blocks carry `Список.Ref` and `~Список.Ref~Список.Ссылка` side
/// by side, plus `Список.DeletionMark` and
/// `~Список.DeletionMark~Список.ПометкаУдаления`. Four further lists on the
/// stand remember a name twice without requiring both ids; they write one entry
/// and are unaffected.
///
/// The order is the map's own suffix numbering. In both observations the map is
/// stored with ascending item ids, so the suffix order and the id order name
/// the same first entry; nothing here distinguishes them.
pub(super) fn parse_form_dynamic_list_shadowed_field_item_ids(
    settings_fields: &[&str],
) -> BTreeSet<String> {
    let mut field_name_by_suffix = BTreeMap::<String, String>::new();
    let mut item_id_by_suffix = BTreeMap::<String, String>::new();
    for pair in settings_fields.chunks_exact(2) {
        collect_form_dynamic_list_field_map_item(
            pair[0],
            pair[1],
            &mut field_name_by_suffix,
            &mut item_id_by_suffix,
        );
        collect_form_dynamic_list_field_map_item(
            pair[1],
            pair[0],
            &mut field_name_by_suffix,
            &mut item_id_by_suffix,
        );
    }
    let mut declared = field_name_by_suffix
        .iter()
        .filter_map(|(suffix, field_name)| {
            let position = suffix.parse::<u64>().ok()?;
            let item_id = item_id_by_suffix.get(suffix)?;
            Some((position, item_id.as_str(), field_name.as_str()))
        })
        .collect::<Vec<_>>();
    declared.sort_unstable();
    let mut claimed = BTreeMap::<&str, &str>::new();
    let mut shadowed = BTreeSet::new();
    for (_, item_id, field_name) in declared {
        match claimed.get(field_name) {
            Some(owner) if *owner != item_id => {
                shadowed.insert(item_id.to_string());
            }
            Some(_) => {}
            None => {
                claimed.insert(field_name, item_id);
            }
        }
    }
    shadowed
}

pub(super) fn parse_form_dynamic_list_required_item_ids(settings_fields: &[&str]) -> Vec<String> {
    let mut parsed = Vec::new();
    for window in settings_fields.windows(2) {
        let key = parse_1c_quoted_string_with_len(window[0].trim())
            .map(|(value, _)| value)
            .unwrap_or_default();
        if key.starts_with("ReqMapFieldId")
            && let Some(item_id) = parse_form_setting_number(window[1])
        {
            parsed.push(item_id);
        }
    }
    parsed
}

/// Item id `10000000` is the list's default-picture pseudo field. It carries
/// the `~` marker exactly when the picture sits outside the table the list
/// declares -- see
/// [`form_dynamic_list_default_picture_is_out_of_table`], which reads the same
/// test the row-picture slot reads, measured over all 6 211 `DefaultPicture`
/// paths of the stand.
///
/// Item id `-3` is the list's grouping pseudo field, written `Group`. The single
/// platform observation (UT 11.5.27.75,
/// `DataProcessors/НастройкаПоддержанияЗапасов/Forms/Форма`) carries a real main
/// table and is written plain; the no-main-table shape is unobserved and is
/// refused rather than guessed.
///
/// Item id `-1` is the list's row-order pseudo field, written `Order`, never
/// `~`-marked. Two native ERP УХ 3.2.12.6 observations
/// (`Catalogs/ДокументыПодтверждающиеЛьготыПоИмущественнымНалогам/Forms/ФормаСписка`,
/// `Catalogs/ПравилаГруппировкиАктивовОбязательств/Forms/ФормаСписка`), both
/// with a real main table; the no-main-table shape is unobserved here too and
/// is refused rather than guessed, matching `-3`'s own precedent. This mirrors
/// `resolve_form_dynamic_list_member_data_path`'s independent evidence for the
/// same `-1 -> "Order"` pseudo-field identity in the unrelated item-`DataPath`
/// context (see that function's doc comment) -- a different code path, same
/// platform-declared name for the marker.
///
/// A field resolved through the map is prefixed with `~` exactly when neither
/// of the names the map remembers for it — its own and the localized twin of
/// [`parse_form_dynamic_list_field_secondary_name_by_item_id`] — is in the
/// list's resolvable-field universe (see
/// [`form_dynamic_list_use_always_universe`]), or when an earlier entry of the
/// map already claimed that name (see
/// [`parse_form_dynamic_list_shadowed_field_item_ids`]); with no universe no
/// marker is ever added. A marked field that remembers a twin is written under
/// both names, each carrying its own marker.
pub(super) fn form_dynamic_list_use_always_field_name(
    attribute_name: &str,
    item_id: &str,
    field_name_by_item_id: &BTreeMap<String, String>,
    secondary_name_by_item_id: &BTreeMap<String, String>,
    shadowed_item_ids: &BTreeSet<String>,
    main_table: Option<&str>,
    universe: Option<&BTreeSet<String>>,
) -> Option<String> {
    let has_main_table = main_table.is_some();
    match item_id {
        "10000000" if form_dynamic_list_default_picture_is_out_of_table(main_table) => {
            Some(format!("~{}.DefaultPicture", attribute_name))
        }
        "10000000" => Some(format!("{}.DefaultPicture", attribute_name)),
        "-3" if has_main_table => Some(format!("{}.Group", attribute_name)),
        "-3" => None,
        "-1" if has_main_table => Some(format!("{}.Order", attribute_name)),
        "-1" => None,
        _ => field_name_by_item_id.get(item_id).map(|field_name| {
            let secondary = secondary_name_by_item_id.get(item_id);
            let unresolvable = universe.is_some_and(|universe| {
                !form_dynamic_list_field_item_is_resolvable(
                    item_id,
                    field_name,
                    secondary.map(String::as_str),
                    shadowed_item_ids,
                    universe,
                )
            });
            if unresolvable {
                match secondary {
                    Some(secondary) if secondary != field_name => {
                        format!("~{attribute_name}.{field_name}~{attribute_name}.{secondary}")
                    }
                    _ => format!("~{attribute_name}.{field_name}"),
                }
            } else {
                format!("{attribute_name}.{field_name}")
            }
        }),
    }
}

/// Whether a remembered field-map entry resolves against the list's fields: its
/// name must be one of them, and no earlier entry of the map may have claimed
/// that name already.
pub(super) fn form_dynamic_list_field_item_is_resolvable(
    item_id: &str,
    field_name: &str,
    secondary_name: Option<&str>,
    shadowed_item_ids: &BTreeSet<String>,
    universe: &BTreeSet<String>,
) -> bool {
    !shadowed_item_ids.contains(item_id)
        && form_dynamic_list_field_name_is_resolvable(field_name, secondary_name, universe)
}

/// Whether a remembered field name resolves against the list's field universe.
///
/// The map remembers a standard attribute under its English name and keeps the
/// Russian spelling beside it; both name the same field, so either one
/// resolving is enough.
pub(super) fn form_dynamic_list_field_name_is_resolvable(
    field_name: &str,
    secondary_name: Option<&str>,
    universe: &BTreeSet<String>,
) -> bool {
    universe.contains(field_name)
        || secondary_name.is_some_and(|secondary| universe.contains(secondary))
}

/// The names a dynamic list can resolve against its data source, or `None` when
/// the universe cannot be built — in which case no `~` marker is ever written,
/// which is the pre-existing behavior.
///
/// The model is measured against the platform's own `~` markers over the whole
/// stand — a remembered field is marked exactly when neither the name the field
/// map keeps for it nor its localized twin is in this universe (see
/// [`form_dynamic_list_field_name_is_resolvable`]). On ERP УХ 3.2.12.6 the
/// model agrees with the platform on 8 776 of the 8 864 dynamic-list records,
/// on UT 11.5.27.75 on 1 931 of 1 936, and on БСП demo and base on all of them.
/// The universe is:
///
/// * `ManualQuery=0`: the standard attributes of the main table's family
///   (Russian and English spellings, see
///   [`form_dynamic_list_std_attribute_pairs`]) plus the declared top-level
///   children of the main table read off the object-reference index.
/// * `ManualQuery=1` with `AutoFillAvailableFields` unset or true: the result
///   column names of the query's final `SELECT` batch, plus the main table's
///   standard attributes and register dimensions the platform re-adds on its
///   own — each under the Russian spelling only, and each unless the query
///   already selects that main-table field under a different alias.
/// * `ManualQuery=1` with `AutoFillAvailableFields=false`: only the names the
///   query's `{ВЫБРАТЬ ...}` extension lists.
/// * In every mode: the `dataPath` of each `CalculatedField` the list's
///   `ServerState` declares.
///
/// A `*` selection item is read where the query itself says what it stands
/// for -- see [`form_dynamic_list_star_source_fields`]; where it does not, and
/// on an unparseable input, the universe is a refusal (`None`).
pub(super) fn form_dynamic_list_use_always_universe(
    settings: Option<&FormDynamicListSettings>,
    settings_fields: &[&str],
    object_refs: &BTreeMap<String, String>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Option<BTreeSet<String>> {
    let settings = settings?;
    let mut universe;
    if settings.manual_query {
        let query_text = settings.query_text.as_deref()?;
        if form_dynamic_list_query_names_undeclared_metadata(query_text, declarations) {
            universe = BTreeSet::new();
        } else {
            let selection = parse_form_dynamic_list_query_selection(query_text)?;
            if !parse_form_dynamic_list_auto_fill_available_fields(settings_fields) {
                universe = selection.extension.clone().unwrap_or_default();
            } else {
                universe = selection.aliases.clone();
                for star in &selection.stars {
                    universe.extend(form_dynamic_list_star_source_fields(
                        star.as_deref(),
                        &selection,
                        object_refs,
                        declarations,
                    )?);
                }
                if let Some(main_table) = settings.main_table.as_deref() {
                    universe.extend(form_dynamic_list_main_table_auto_fields(
                        main_table,
                        &selection,
                        object_refs,
                        declarations,
                    )?);
                }
            }
        }
    } else {
        let main_table = settings.main_table.as_deref()?;
        let (kind, rest) = main_table.split_once('.')?;
        if rest.contains('.') {
            // A virtual-table main table on an auto list is unobserved.
            return None;
        }
        if kind == "DocumentJournal" {
            // A journal's columns are addressable fields of the list, and the
            // object-reference index carries no `Column` child at all -- 0 of
            // the whole UT 11.5.27.75 index -- so the universe of a journal
            // main table cannot be built from it. That is a refusal, not an
            // empty universe: an empty one would mark every field of every
            // journal list unresolvable.
            return None;
        }
        let pairs = form_dynamic_list_std_attribute_pairs(kind)?;
        if !object_refs
            .values()
            .any(|reference| reference == main_table)
        {
            return None;
        }
        universe = BTreeSet::new();
        for (ru, en) in
            form_dynamic_list_declared_std_attribute_pairs(pairs, main_table, declarations)
        {
            universe.insert((*ru).to_string());
            universe.insert((*en).to_string());
        }
        universe.extend(form_dynamic_list_main_table_children(
            main_table,
            object_refs,
            FORM_DYNAMIC_LIST_MAIN_TABLE_CHILD_KINDS,
        ));
        // A common attribute is a field of the tables its own `<Content>`
        // puts it on, spelled the same on all of them. A configuration whose
        // common attributes this reader cannot decode admits all of their
        // names, as it did before it could read the content at all.
        universe.extend(
            object_refs
                .values()
                .filter_map(|reference| reference.strip_prefix("CommonAttribute."))
                .filter(|name| !name.is_empty() && !name.contains('.'))
                .filter(|name| {
                    form_dynamic_list_table_carries_common_attribute(declarations, main_table, name)
                })
                .map(str::to_string),
        );
    }
    if let Some(server_state_xml) = &settings.server_state_xml {
        universe.extend(form_dynamic_list_calculated_field_data_paths(
            server_state_xml,
        ));
    }
    Some(universe)
}

/// The result column names one `*` item of a manual query's final selection
/// stands for: the fields of the FROM source it is qualified with.
///
/// `<alias>.*` names the source declared under that alias, so its result
/// columns are that table's own fields -- the standard attributes the table
/// declares (in the Russian spelling a query result carries, the same rule
/// [`form_dynamic_list_main_table_auto_fields`] states) plus its declared
/// top-level children. Everything else about a star is a refusal, and a
/// refusal here refuses the whole universe, exactly as the unconditional
/// refusal this replaces did: a bare `*`, a tabular-section star
/// (`<alias>.<section>.*`), a star on a parenthesized expression, an alias no
/// FROM source of that select declares, a source that is a subquery or a
/// temporary table, a virtual table (whose columns are not the base table's),
/// a table the object-reference index does not carry, and a family whose
/// standard attributes this reader cannot name.
///
/// Evidence, ERP УХ 3.2.12.6: 71 `<UseAlways>` blocks over 35 regulated-report
/// forms whose list reads `ВЫБРАТЬ РегистрСведений.*, &ПустаяКартинкаСтрок КАК
/// ПустаяКартинка ИЗ РегистрСведений.<X> КАК РегистрСведений`. The platform
/// marks exactly the remembered names that register does not declare, and
/// writes the rest plain — `Reports/РегламентированныйОтчетАлкоПриложение25/
/// Forms/ФормаОтчета2021Кв1` marks `ИндексСтраницы` (the register spells the
/// field `ИДДокИндСтраницы`) and, on its `Раздел3Возвраты` list, every
/// `П00002…` name the field map kept from a `Раздел2Поступления` source, while
/// its `Раздел2Поступления` list writes `П000020000301`…`П000020000313`,
/// `Активно`, `Документ` and `ИндексСтроки` plain because that register
/// declares them.
///
/// The whole stand carries 192 manual-query dynamic lists whose final selection
/// has a star, and this reader's own parse splits them into four shapes:
///
/// | shape | records | platform marks |
/// |---|---:|---:|
/// | `<alias>.*` over a base table (readable) | 71 (`uh`) | 71 |
/// | `<alias>.<section>.*` | 111 (`uh` 56, `ut` 48, `do` 7) | 0 |
/// | star qualifier names no FROM source of that select | 9 (`uh` 2, `ut` 2, `do` 1, `ssl` 2, `sslbase` 2) | 0 |
/// | bare `*` | 1 (`uh`) | 0 |
///
/// Every record of the readable shape carries a marker and every record of the
/// other three is written plain, which is what a refused universe already
/// writes — so reading the readable shape and refusing the rest moves 71
/// records and no other.
fn form_dynamic_list_star_source_fields(
    qualifier: Option<&str>,
    selection: &FormDynamicListQuerySelection,
    object_refs: &BTreeMap<String, String>,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> Option<BTreeSet<String>> {
    let alias = qualifier?;
    let table = selection
        .sources
        .iter()
        .find_map(|(reference, source_alias)| {
            (source_alias.as_deref() == Some(alias))
                .then(|| reference.clone())
                .flatten()
        })?;
    // `Kind.Name` only: a virtual table's columns are not the base table's.
    if table.matches('.').count() != 1 {
        return None;
    }
    if !object_refs.values().any(|reference| reference == &table) {
        return None;
    }
    let (kind, _) = table.split_once('.')?;
    let pairs = form_dynamic_list_std_attribute_pairs(kind)?;
    let mut fields = BTreeSet::new();
    for (ru, _) in form_dynamic_list_declared_std_attribute_pairs(pairs, &table, declarations) {
        fields.insert((*ru).to_string());
    }
    fields.extend(form_dynamic_list_main_table_children(
        &table,
        object_refs,
        FORM_DYNAMIC_LIST_MAIN_TABLE_CHILD_KINDS,
    ));
    Some(fields)
}

/// Whether the query names metadata the configuration does not declare.
///
/// A `ЗНАЧЕНИЕ(...)` literal naming a table no metadata record declares is a
/// query that cannot compile, and a dynamic list whose query does not compile
/// has no available fields at all: the platform marks every field the map
/// remembers.
///
/// Evidence: ERP УХ MDM_Management 3.2.12.6,
/// `Documents/ЗаявкаНаИзменениеНСИ/Forms/ФормаСписка` and `.../ФормаВыбора`,
/// whose query selects
/// `ЗНАЧЕНИЕ(Перечисление.СостоянияСогласования.Черновик)` while the
/// configuration declares `Enum.СостоянияСогласованияНСИ` and no
/// `СостоянияСогласования` at all; all eight remembered fields of each list
/// carry the `~` marker on their item `<DataPath>`. Over the whole stand these
/// two are the only dynamic lists whose query names undeclared metadata: the
/// other 2 226 ERP УХ, 1 025 UT, 497 Документооборот, 173 БСП demo and 148 БСП
/// base manual-query lists name only declared metadata, and ten lists that look
/// like counter-examples name it in a different case, which the query language
/// resolves and this reader does too.
///
/// Only the `ЗНАЧЕНИЕ(...)` literal is read here. A `FROM` source naming
/// undeclared metadata is the same failure in principle and has no observation
/// on the stand, so it is left alone rather than guessed at.
fn form_dynamic_list_query_names_undeclared_metadata(
    query_text: &str,
    declarations: Option<&MetadataFieldDeclarationIndex>,
) -> bool {
    let Some(declarations) = declarations else {
        return false;
    };
    let tokens = tokenize_1c_query(query_text);
    for window in tokens.windows(5) {
        if !is_1c_query_keyword(&window[0], Q_VALUE_LITERAL) || window[1] != "(" || window[3] != "."
        {
            continue;
        }
        let kind_upper = window[2].to_uppercase();
        let Some(kind) = Q_RU_SOURCE_KINDS
            .iter()
            .find_map(|(ru, en)| (*ru == kind_upper).then_some(*en))
        else {
            continue;
        };
        if !is_1c_query_ident(&window[4]) {
            continue;
        }
        if declarations.declares_table(&format!("{kind}.{}", window[4])) == Some(false) {
            return true;
        }
    }
    false
}

/// The family's standard attributes filtered down to the ones the main table
/// declares -- a catalog with `<CodeLength>0</CodeLength>` has no `Code` for a
/// list to resolve `Code` or `Код` against, and the platform marks it.
///
/// Evidence, ERP УХ 3.2.12.6: `Catalog.КатегорииЗакупок` and
/// `Catalog.УдалитьПанелиОтчетов` (`CodeLength` 0),
/// `Catalog.КодыВидовРасхода` (`DescriptionLength` 0),
/// `Catalog.ИнтервалыЗадолженностей` and
/// `Catalog.РазделыИнвестиционныхПрограмм` (empty `<Owners/>`),
/// `Catalog.ОбщероссийскийКлассификаторОсновныхФондов` (`HierarchyOfItems`,
/// so no `IsFolder`) and the non-periodical
/// `InformationRegister.НоменклатураАккредитованыхПоставщиков`; Документооборот
/// КОРП 3.0.21.3 `Catalog.СостоянияЧатБота` (`HierarchyOfItems`). Every one is
/// written with the platform's `~` marker and was written plain before.
///
/// A table the declaration index does not carry keeps the whole family table,
/// which is what the reader did before it could read a declaration at all.
fn form_dynamic_list_declared_std_attribute_pairs<'a>(
    pairs: &'a [(&'static str, &'static str)],
    main_table: &'a str,
    declarations: Option<&'a MetadataFieldDeclarationIndex>,
) -> impl Iterator<Item = &'a (&'static str, &'static str)> {
    let declared = declarations.and_then(|index| index.table(main_table));
    pairs
        .iter()
        .filter(move |(_, en)| declared.is_none_or(|declared| declared.declares(en)))
}

/// Whether a common attribute is a field of `main_table`, by its own declared
/// `<Content>`. A common attribute the declaration index does not carry is a
/// field of every table, as before.
fn form_dynamic_list_table_carries_common_attribute(
    declarations: Option<&MetadataFieldDeclarationIndex>,
    main_table: &str,
    name: &str,
) -> bool {
    declarations
        .and_then(|index| index.common_attribute(name))
        .is_none_or(|content| content.covers(main_table))
}

/// `AutoFillAvailableFields` as the list-settings bag spells it; absent means
/// the platform default, which fills the available-field list from the query.
pub(super) fn parse_form_dynamic_list_auto_fill_available_fields(settings_fields: &[&str]) -> bool {
    for window in settings_fields.windows(2) {
        let key = parse_1c_quoted_string_with_len(window[0].trim())
            .map(|(value, _)| value)
            .unwrap_or_default();
        if key == "AutoFillAvailableFields"
            && let Some(value) = parse_form_setting_bool(window[1])
        {
            return value;
        }
    }
    true
}

/// `dataPath` of every `CalculatedField` a normalized `ServerState` fragment
/// declares. The fragment is scanned rather than parsed: the writer emits it
/// verbatim, so the element spelling here is exactly the emitted one.
fn form_dynamic_list_calculated_field_data_paths(server_state_xml: &str) -> Vec<String> {
    let mut names = Vec::new();
    let mut rest = server_state_xml;
    while let Some(start) = rest.find("<CalculatedField>") {
        rest = &rest[start + "<CalculatedField>".len()..];
        let trimmed = rest.trim_start();
        let Some(path_body) = trimmed.strip_prefix("<dcssch:dataPath>") else {
            continue;
        };
        let Some(end) = path_body.find('<') else {
            break;
        };
        names.push(path_body[..end].to_string());
    }
    names
}

/// Child kinds whose names are addressable as fields of a dynamic list's main
/// table. Command, Form, Template and nested tabular-section attributes are
/// not: a required-field name never resolves through them.
const FORM_DYNAMIC_LIST_MAIN_TABLE_CHILD_KINDS: &[&str] = &[
    "Attribute",
    "TabularSection",
    "Dimension",
    "Resource",
    "AddressingAttribute",
    "AccountingFlag",
    "ExtDimensionAccountingFlag",
    "EnumValue",
];

/// Declared top-level children of a metadata table, read off the same
/// object-reference index the rest of the form decoder resolves through:
/// every `{table}.{kind}.{name}` reference contributes `name` when `kind` is
/// in `kinds`.
fn form_dynamic_list_main_table_children(
    table: &str,
    object_refs: &BTreeMap<String, String>,
    kinds: &[&str],
) -> BTreeSet<String> {
    let prefix = format!("{table}.");
    let mut names = BTreeSet::new();
    for reference in object_refs.values() {
        let Some(rest) = reference.strip_prefix(&prefix) else {
            continue;
        };
        let Some((kind, name)) = rest.split_once('.') else {
            continue;
        };
        if !name.is_empty() && !name.contains('.') && kinds.contains(&kind) {
            names.insert(name.to_string());
        }
    }
    names
}

