pub(super) fn parse_form_column_group_options(fields: &[&str]) -> Option<FormColumnGroupOptions> {
    let options_text = fields.get(FormColumnGroupSchema::OPTIONS_SLOT)?.trim();
    if scan_1c_braced_value(options_text, 0) != Some(options_text.len()) {
        return None;
    }
    let options = split_1c_braced_fields(options_text, 0)?;
    if !matches!(options.first()?.trim(), "2" | "5") {
        return None;
    }
    let strict_schema = FormColumnGroupSchema::from_raw_layout(
        fields.first()?.trim(),
        fields.len(),
        "ColumnGroup",
        fields.get(5).map(|field| field.trim()),
        &options,
    );
    Some(FormColumnGroupOptions {
        group: options
            .get(1)
            .and_then(|field| parse_form_column_group_group(field)),
        show_in_header: options
            .get(3)
            .and_then(|field| parse_form_child_item_show_title(field)),
        header_horizontal_align: parse_form_column_group_header_horizontal_align(&options),
        fixing_in_table: strict_schema.and_then(|schema| schema.fixing_in_table(&options)),
    })
}

pub(super) fn parse_form_standalone_undefined_marker(field: &str) -> Option<bool> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    (fields.len() == 1
        && fields
            .first()
            .and_then(|field| parse_1c_string(field))
            .is_some_and(|marker| marker == "U"))
    .then_some(true)
}

pub(super) fn form_table_ordinary_layout_variant(fields: &[&str]) -> bool {
    fields.get(43).map(|field| field.trim()) == Some("{0}")
        || (fields.get(55).map(|field| field.trim()) == Some(TableTailKey::RowFilter.key())
            && fields
                .get(56)
                .and_then(|field| parse_form_standalone_undefined_marker(field.trim()))
                == Some(true)
            && fields.get(57).map(|field| field.trim()) == Some("19"))
}

pub(super) fn form_table_has_hierarchical_navigation(item: &FormChildItem) -> bool {
    item.tag == "Table"
        && (item.show_root == Some(true)
            || item.allow_root_choice.is_some()
            || item.top_level_parent_nil == Some(true))
}

pub(super) fn parse_form_label_field_options(
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<FormLabelFieldOptions> {
    let options_index = 39 + form_input_field_top_level_offset(fields);
    let options = split_1c_braced_fields(fields.get(options_index)?.trim(), 0)?;
    if options.first()?.trim() != "11" {
        return None;
    }
    // `Hiperlink` has its own flag in slot 7; it is not a shape inferred from
    // which geometry members happen to be set. The geometry members below sit
    // in the tail of the tuple (slots 15..19), which is why a hyperlink label
    // used to look like a label whose `<Width>` had gone missing.
    let hyperlink_style = options
        .get(LabelFieldSlot::Hiperlink.index())
        .map(|field| field.trim())
        == Some("1");
    Some(FormLabelFieldOptions {
        width: parse_form_label_field_extent(&options, LabelFieldSlot::Width),
        height: parse_form_label_field_extent(&options, LabelFieldSlot::Height),
        auto_max_width: parse_form_label_field_auto_max(&options, LabelFieldSlot::AutoMaxWidth),
        max_width: parse_form_label_field_extent(&options, LabelFieldSlot::MaxWidth),
        auto_max_height: parse_form_label_field_auto_max(&options, LabelFieldSlot::AutoMaxHeight),
        max_height: parse_form_label_field_extent(&options, LabelFieldSlot::MaxHeight),
        horizontal_stretch: parse_form_label_field_stretch(
            &options,
            LabelFieldSlot::HorizontalStretch,
        ),
        vertical_stretch: parse_form_label_field_stretch(&options, LabelFieldSlot::VerticalStretch),
        format: options
            .get(LabelFieldSlot::Format.index())
            .map(|field| parse_form_localized_strings(field))
            .unwrap_or_default(),
        font_xml: options
            .get(LabelFieldSlot::Font.index())
            .and_then(|field| parse_form_font_tuple_xml(field, object_refs)),
        text_color: options
            .get(LabelFieldSlot::TextColor.index())
            .and_then(|field| parse_form_label_field_text_color(field, object_refs)),
        password_mode: match options
            .get(LabelFieldSlot::PasswordMode.index())
            .map(|field| field.trim())
        {
            Some("0") => Some(false),
            _ => None,
        },
        mark_negatives: parse_form_option_mark_negatives(
            &options,
            LabelFieldSlot::MarkNegatives.index(),
        ),
        hyperlink_style,
    })
}

/// A zero extent slot means the platform writes no element at all.
fn parse_form_label_field_extent(options: &[&str], slot: LabelFieldSlot) -> Option<String> {
    options
        .get(slot.index())
        .map(|field| field.trim())
        .filter(|value| *value != "0" && value.parse::<u32>().is_ok())
        .map(str::to_string)
}

/// The auto-max flags default to on and are only written when switched off.
fn parse_form_label_field_auto_max(options: &[&str], slot: LabelFieldSlot) -> Option<bool> {
    match options.get(slot.index()).map(|field| field.trim()) {
        Some("0") => Some(false),
        _ => None,
    }
}

/// The stretch flags carry a third `2` state that means "unset".
fn parse_form_label_field_stretch(options: &[&str], slot: LabelFieldSlot) -> Option<bool> {
    match options.get(slot.index()).map(|field| field.trim()) {
        Some("0") => Some(false),
        Some("1") => Some(true),
        _ => None,
    }
}

pub(super) fn parse_form_label_field_text_color(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.first().map(|value| value.trim()) != Some("3") {
        return None;
    }
    match fields.get(1).map(|value| value.trim()) {
        Some("3") => {
            if let Some(reference) = parse_moxel_style_ref_slot(field, object_refs).flatten() {
                return Some(reference);
            }
            parse_form_object_reference(fields.get(2)?.trim(), object_refs).map(|reference| {
                reference
                    .strip_prefix("StyleItem.")
                    .map(|name| format!("style:{name}"))
                    .unwrap_or(reference)
            })
        }
        Some("2") | Some("0") => parse_moxel_style_ref_slot(field, object_refs).flatten(),
        _ => None,
    }
}

/// Every control colour of a form item is one and the same three-member value
/// `{3, <space>, <payload>}`; the colour space in the middle picks how the
/// payload reads, and space `4` with payload `{0}` is the platform's "unset"
/// encoding, which writes no element at all.
///
/// Space, payload shape and written value were read off the 6 816 colour
/// elements the platform writes on the 5 201 native `Form.xml` of
/// 1С:Управление торговлей 11.5.27.75, joined to the raw layout bytes of the
/// item that carries them. Every raw tuple observed there maps to exactly one
/// written value, and the shape alone decides whether an element is written:
/// across ~250 000 item/slot observations `{3,4,{0}}` never coincides with a
/// written element and no other shape ever coincides with its absence.
pub(super) fn parse_form_control_color(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let color = split_1c_braced_fields(field.trim(), 0)?;
    if color.len() != 3 || color.first()?.trim() != "3" {
        return None;
    }
    parse_form_control_color_space(color.get(1)?.trim(), color.get(2)?.trim(), object_refs)
}

/// One colour space and its payload, shared by every slot that carries a colour.
fn parse_form_control_color_space(
    space: &str,
    payload: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let payload = split_1c_braced_fields(payload, 0)?;
    match space {
        "0" if payload.len() == 1 => {
            let value = payload.first()?.trim().parse::<u32>().ok()? & 0x00ff_ffff;
            let red = value & 0xff;
            let green = (value >> 8) & 0xff;
            let blue = (value >> 16) & 0xff;
            Some(format!("#{red:02X}{green:02X}{blue:02X}"))
        }
        "1" if payload.len() == 1 => payload
            .first()?
            .trim()
            .parse::<i32>()
            .ok()
            .and_then(form_control_window_color_name)
            .map(ToOwned::to_owned),
        "2" if payload.len() == 1 => payload
            .first()?
            .trim()
            .parse::<i32>()
            .ok()
            .and_then(form_control_web_color_name)
            .map(ToOwned::to_owned),
        "3" if payload.len() == 1 => payload
            .first()?
            .trim()
            .parse::<i32>()
            .ok()
            .and_then(form_control_system_color_name)
            .map(ToOwned::to_owned),
        "3" if payload.len() == 2 && payload.first()?.trim() == "0" => {
            let uuid = parse_non_zero_uuid(payload.get(1)?.trim())?;
            object_refs
                .get(&uuid)
                .and_then(|reference| reference.strip_prefix("StyleItem."))
                .map(|name| format!("style:{name}"))
        }
        "4" if payload.len() == 1 && payload.first()?.trim() == "0" => None,
        _ => None,
    }
}

/// Style-palette entries of colour space `3`.
///
/// Read off every space-3 colour the platform writes on the native form dumps
/// of 1С:Управление торговлей 11.5.27.75; the observation count of each code
/// follows its arm. This is a different palette from the one the style and
/// spreadsheet decoders read, and the two disagree on six shared codes, so a
/// form colour never goes through `style_system_color_name`.
pub(super) fn form_control_system_color_name(code: i32) -> Option<&'static str> {
    match code {
        -1 => Some("style:FormBackColor"),              // 120
        -3 => Some("style:FormTextColor"),              // 339
        -7 => Some("style:ButtonBackColor"),            // 68
        -10 => Some("style:FieldBackColor"),            // 37
        -11 => Some("style:FieldTextColor"),            // 14
        -13 => Some("style:FieldAlternativeBackColor"), // 11
        -14 => Some("style:FieldSelectionBackColor"),   // 26
        -15 => Some("style:FieldSelectedTextColor"),    // 86
        -16 => Some("style:SpecialTextColor"),          // 98
        -17 => Some("style:NegativeTextColor"),         // 4
        -21 => Some("style:ButtonTextColor"),           // 951
        -22 => Some("style:BorderColor"),               // 35
        -23 => Some("style:ToolTipBackColor"),          // 169
        -24 => Some("style:ToolTipTextColor"),          // 108
        -25 => Some("style:ReportHeaderBackColor"),     // 7
        -26 => Some("style:ReportGroup1BackColor"),     // 3
        -27 => Some("style:ReportGroup2BackColor"),     // 5
        -28 => Some("style:ReportLineColor"),           // 1
        -34 => Some("style:ButtonBorderColor"),         // 23
        -35 => Some("style:TableHeaderBackColor"),      // 87
        -36 => Some("style:TableHeaderTextColor"),      // 19
        -37 => Some("style:TableFooterBackColor"),      // 3
        -42 => Some("style:NavigationColor"),           // 5
        -43 => Some("style:AuxiliaryNavigationColor"),  // 2
        -44 => Some("style:ActivityColor"),             // 3
        -46 => Some("style:AccentColor"),               // 63
        -47 => Some("style:ImportantColor"),            // 32
        _ => None,
    }
}

/// Window-palette entries of colour space `1`, from the native form dumps.
fn form_control_window_color_name(code: i32) -> Option<&'static str> {
    match code {
        4 => Some("win:MenuBar"),       // 12
        17 => Some("win:DisabledText"), // 2
        18 => Some("win:ButtonText"),   // 10
        // Read off the platform's own element the same way the other three
        // were: ERP УХ `Catalogs/ДокументыРеализацииПолномочийНалоговыхОрганов/
        // Forms/ФормаЭлемента` holds `{3,1,{21}}` on the one label decoration
        // whose native document writes `<TextColor>win:ButtonDarkShadow</...>`.
        // Without it the whole colour declined and the element went unwritten.
        21 => Some("win:ButtonDarkShadow"), // 1
        // Two more codes from the same join, run over the dumped item layouts
        // of all seven stand corpora that carry forms: for every item record
        // holding exactly one space-`1` colour tuple whose native element's own
        // scalar run writes exactly one `win:` value, the code and the name are
        // forced on each other. The pairing produces six distinct codes with no
        // ambiguity at all -- not one code maps to two names -- and it
        // reproduces the four above, index for index. The two it adds are the
        // ones the table did not carry, and each of them cost the element
        // outright: ERP УХ
        // `DataProcessors/АналитическийБланкСводнаяТаблица/Forms/
        // ФормаНастройкиРасположенияИзмерений` writes
        // `<BorderColor>win:ActiveTitleBar</BorderColor>` on three of its
        // tables, and `DataProcessors/ДокументооборотСКонтролирующимиОрганами/
        // Forms/ДиагностикаОтчетности_ГлавноеОкно` writes
        // `<BorderColor>win:ScrollBar</BorderColor>` on its `НадписьОтправить`
        // label decoration. Both codes are the Win32 system-colour index the
        // other four already are (`COLOR_SCROLLBAR` 0, `COLOR_ACTIVECAPTION` 2,
        // `COLOR_MENU` 4, `COLOR_GRAYTEXT` 17, `COLOR_BTNTEXT` 18,
        // `COLOR_3DDKSHADOW` 21).
        0 => Some("win:ScrollBar"),      // 1
        2 => Some("win:ActiveTitleBar"), // 3
        _ => None,
    }
}

/// Web-palette entries of colour space `2`.
///
/// The forms corpus exercises fourteen palette indexes the shared style table
/// does not carry, and one -- 31 -- where the platform's own form export
/// contradicts it: the shared table reads 31 as `DarkGreen`, a value it already
/// gives 27, while the native dump writes `DarkOrange` for it. On the remaining
/// eight indexes both cover the two agree exactly, so the shared table stays
/// the fallback and this one carries the form evidence in front of it.
///
/// Five more indexes come from a join of the dumped layouts of all eight stand
/// corpora to the platform's own elements: for every item record that holds
/// exactly one space-`2` colour tuple and whose native element writes exactly
/// one `web:` value, the code and the name are forced on each other. That
/// pairing produces 32 distinct codes with no ambiguity at all -- not one code
/// maps to two names -- and it reproduces every one of the 27 codes the two
/// existing tables already answer, index for index, including the `31`
/// override. The five it adds are the ones neither table carried:
/// `14`/`91`/`106`/`122`/`132`. An unmapped code declines the whole colour, so
/// each of them cost the element outright.
fn form_control_web_color_name(code: i32) -> Option<&'static str> {
    match code {
        1 => Some("web:AliceBlue"),       // 6
        6 => Some("web:Beige"),           // 7
        14 => Some("web:CadetBlue"),      // 1
        30 => Some("web:DarkOliveGreen"), // 3
        31 => Some("web:DarkOrange"),     // 2
        41 => Some("web:DeepSkyBlue"),    // 1
        42 => Some("web:DimGray"),        // 22
        43 => Some("web:DodgerBlue"),     // 1
        57 => Some("web:IndianRed"),      // 1
        70 => Some("web:LightGreen"),     // 15
        75 => Some("web:LightSkyBlue"),   // 1
        91 => Some("web:MediumSeaGreen"), // 6
        100 => Some("web:NavajoWhite"),   // 2
        106 => Some("web:OrangeRed"),     // 2
        109 => Some("web:PaleGreen"),     // 5
        115 => Some("web:Pink"),          // 4
        122 => Some("web:SaddleBrown"),   // 20
        132 => Some("web:Snow"),          // 2
        143 => Some("web:White"),         // 12
        // Three codes the same join names that neither this table nor the
        // shared style palette behind it answers. Re-run over the dumped item
        // layouts of all seven stand corpora that carry forms, item by item
        // rather than file by file, the pairing produces 46 distinct codes with
        // no ambiguity, reproduces every code the two tables already answer --
        // 43 of them, index for index, including the `31` override -- and
        // leaves exactly these three unanswered. Each cost the element
        // outright: ERP УХ
        // `DataProcessors/ДокументооборотСКонтролирующимиОрганами/Forms/
        // Мастер_ПаспортныеДанные` writes `<TextColor>web:LightSalmon</...>` on
        // its `КраснаяРазделительнаяЛиния` label decoration and
        // `<BorderColor>web:LightSalmon</...>` on its `Силуэт` picture
        // decoration; `DataProcessors/АналитическийБланкСводнаяТаблица/Forms/
        // ФормаМакетаСводнаяТаблица` writes `web:Lime`; and
        // `Documents/ЗаказНаПроизводство2_2/Forms/ФормаДокумента` writes
        // `web:PapayaWhip`.
        73 => Some("web:LightSalmon"), // 2
        80 => Some("web:Lime"),        // 1
        112 => Some("web:PapayaWhip"), // 2
        _ => style_web_color_name(code),
    }
}

pub(super) fn parse_form_label_decoration_options(
    item_tag: &str,
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<FormLabelDecorationOptions> {
    let options = split_1c_braced_fields(
        fields.get(FormLabelDecorationSchema::OPTIONS_SLOT)?.trim(),
        0,
    )?;
    let schema = FormLabelDecorationSchema::from_raw_layout(
        fields.first()?.trim(),
        fields.len(),
        item_tag,
        fields.get(5).map(|field| field.trim()),
        &options,
    )?;
    Some(FormLabelDecorationOptions {
        hyperlink: options.get(1).map(|field| field.trim()) == Some("1"),
        font_xml: fields
            .get(FORM_LABEL_DECORATION_FONT_SLOT)
            .and_then(|field| parse_form_font_tuple_xml(field, object_refs)),
        text_color: fields
            .get(14)
            .and_then(|field| parse_form_control_color(field, object_refs)),
        back_color: options
            .get(6)
            .and_then(|field| parse_form_control_color(field, object_refs)),
        border_color: options
            .get(FormLabelDecorationSchema::BORDER_COLOR_OPTION_SLOT)
            .and_then(|field| parse_form_control_color(field, object_refs)),
        group_horizontal_align: fields
            .get(schema.group_horizontal_align_slot())
            .and_then(|field| parse_form_label_decoration_group_horizontal_align(field)),
        alignment: schema.alignment(fields, &options),
        geometry: schema.geometry(fields),
        visual_tail: schema.visual_tail(&options),
        skip_on_input: schema.skip_on_input(fields),
    })
}

/// Title colour of the grouping controls -- `UsualGroup` and its `Popup`,
/// `Page` and `ColumnGroup` siblings -- which all keep it in the same top-level
/// slot 16, one slot ahead of the title font tuple they also share.
///
/// The slot holds an ordinary control colour, so it goes through the one colour
/// grammar; the only extra shape is the four-member `{4, 3, <payload>, 3}`
/// spelling of the same space-3 value.
pub(super) fn parse_form_usual_group_title_text_color(
    fields: &[&str],
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let field = fields.get(FORM_GROUP_TITLE_TEXT_COLOR_SLOT)?.trim();
    if let Some(value) = parse_form_control_color(field, object_refs) {
        return Some(value);
    }
    let color = split_1c_braced_fields(field, 0)?;
    if color.len() != 4
        || color.first()?.trim() != "4"
        || color.get(1)?.trim() != "3"
        || color.get(3)?.trim() != "3"
    {
        return None;
    }
    parse_form_control_color_space("3", color.get(2)?.trim(), object_refs)
}

/// `UsualGroup`, `Popup`, `Page` and `ColumnGroup` all carry `TitleTextColor`
/// here: on the 45 225 grouping items of the native UT 11.5.27.75 form dumps
/// the slot holds the unset colour on every item without the element and a
/// readable colour on every one of the 335 items that carry it, with no
/// counter-example in either direction.
const FORM_GROUP_TITLE_TEXT_COLOR_SLOT: usize = 16;

/// `Table` keeps the same property in slot 49: unset on all 4 489 tables
/// without the element, a style reference on all 20 that carry it.
const FORM_TABLE_TITLE_TEXT_COLOR_SLOT: usize = 49;

/// The grouping child items -- `UsualGroup` and its `Popup`/`Pages`/`Page`/
/// `ColumnGroup` siblings -- all carry their title font in the same top-level
/// slot 17.
pub(super) const FORM_GROUP_TITLE_FONT_SLOT: usize = 17;

/// The child items that share the grouping layout: their geometry sits in the
/// same four top-level slots ahead of the title colour and title font.
pub(super) const FORM_GROUP_LAYOUT_TAGS: [&str; 7] = [
    "UsualGroup",
    "Popup",
    "Pages",
    "Page",
    "ColumnGroup",
    "CommandBar",
    "ButtonGroup",
];

/// A grouping item closes its tuple with its alignment pair, counted back from
/// the end so the inline child items in the middle cannot move it: `len - 3`
/// holds the group horizontal alignment and `len - 2` the vertical one. Both
/// use `0`/`1`/`2` for the near end, the centre and the far end, and `3` for
/// the platform default the XML omits.
///
/// The window is a property of the record tail, not of the tag, so it is read
/// by layout rather than by name. Measured against the native
/// "1С:Управление торговлей" 11.5.27.75 tree over every record the export
/// walks, the pair is a total function of the platform answer on each owner
/// with no counter-example in either direction: `Pages` 2 373 records, `Page`
/// 7 016 records (4 `GroupVerticalAlign`), `ColumnGroup` 3 008 records (1
/// `GroupHorizontalAlign`, 4 `GroupVerticalAlign`) and `ButtonGroup` 7 333
/// records (8 and 2). Every record without the element reads `3`.
const FORM_PAGES_GROUP_HORIZONTAL_ALIGN_FROM_END: usize = 3;
const FORM_PAGES_GROUP_VERTICAL_ALIGN_FROM_END: usize = 2;

/// A `Table` closes its tuple with the same pair seven slots further in, which
/// is what keeps it in place across the several `Table` layout lengths: over
/// all 4 543 `Table` records the export walks, `len - 10` reads `3` on the
/// 4 540 tables without a `<GroupHorizontalAlign>` and `0`/`1` on exactly the
/// 2 `Left` and 1 `Center`, and `len - 9` reads `3` on the 4 542 without a
/// `<GroupVerticalAlign>` and `2` on the one `Bottom`.
const FORM_TABLE_GROUP_HORIZONTAL_ALIGN_FROM_END: usize = 10;
const FORM_TABLE_GROUP_VERTICAL_ALIGN_FROM_END: usize = 9;

/// The grouping items whose alignment pair rides the shared record tail.
pub(super) fn form_group_tail_align_tag(tag: &str) -> bool {
    matches!(tag, "Pages" | "Page" | "ColumnGroup" | "ButtonGroup")
}

fn parse_form_pages_group_align(
    tag: &str,
    fields: &[&str],
    from_end: usize,
    values: [&'static str; 3],
) -> Option<&'static str> {
    let from_end = if form_group_tail_align_tag(tag) {
        from_end
    } else if tag == "Table" {
        match from_end {
            FORM_PAGES_GROUP_HORIZONTAL_ALIGN_FROM_END => {
                FORM_TABLE_GROUP_HORIZONTAL_ALIGN_FROM_END
            }
            FORM_PAGES_GROUP_VERTICAL_ALIGN_FROM_END => FORM_TABLE_GROUP_VERTICAL_ALIGN_FROM_END,
            _ => return None,
        }
    } else {
        return None;
    };
    let slot = fields.len().checked_sub(from_end)?;
    match fields.get(slot)?.trim() {
        "0" => Some(values[0]),
        "1" => Some(values[1]),
        "2" => Some(values[2]),
        _ => None,
    }
}

pub(super) const FORM_GROUP_WIDTH_SLOT: usize = 12;
pub(super) const FORM_GROUP_HEIGHT_SLOT: usize = 13;
pub(super) const FORM_GROUP_HORIZONTAL_STRETCH_SLOT: usize = 14;
pub(super) const FORM_GROUP_VERTICAL_STRETCH_SLOT: usize = 15;

pub(super) fn form_group_layout_tag(tag: &str) -> bool {
    FORM_GROUP_LAYOUT_TAGS.contains(&tag)
}

/// A `Table`'s max-extent geometry sits in a fixed window counted back from
/// the end of the item tuple, which is what keeps it in place across the
/// several `Table` layout lengths.
const FORM_TABLE_AUTO_MAX_WIDTH_FROM_END: usize = 15;
const FORM_TABLE_MAX_WIDTH_FROM_END: usize = 14;
const FORM_TABLE_AUTO_MAX_HEIGHT_FROM_END: usize = 12;
const FORM_TABLE_MAX_HEIGHT_FROM_END: usize = 11;
const FORM_TABLE_HORIZONTAL_STRETCH_SLOT: usize = 41;
const FORM_TABLE_VERTICAL_STRETCH_SLOT: usize = 42;
pub(super) const FORM_TABLE_FONT_SLOT: usize = 48;
pub(super) const FORM_TABLE_TITLE_FONT_SLOT: usize = 50;

/// `LabelDecoration` and `PictureDecoration` share a layout whose font tuple
/// sits in top-level slot 15.
pub(super) const FORM_LABEL_DECORATION_FONT_SLOT: usize = 15;

fn form_table_tail_slot<'a>(fields: &[&'a str], from_end: usize) -> Option<&'a str> {
    fields
        .len()
        .checked_sub(from_end)
        .and_then(|slot| fields.get(slot))
        .map(|field| field.trim())
}

fn parse_form_table_max_extent(tag: &str, fields: &[&str], from_end: usize) -> Option<String> {
    if tag != "Table" {
        return None;
    }
    form_table_tail_slot(fields, from_end)
        .filter(|value| *value != "0" && value.parse::<u32>().is_ok())
        .map(str::to_string)
}

/// The `Table` auto-max and stretch flags default to on; only the `0` state
/// reaches the XML.
fn parse_form_table_off_flag(tag: &str, value: Option<&str>) -> Option<bool> {
    if tag != "Table" {
        return None;
    }
    (value? == "0").then_some(false)
}

/// Geometry slots of the document-field option tuple in top-level slot 39.
///
/// Each document field kind has its own discriminator, its own tuple length
/// and its own tail slots, but they all share the same shape: an extent slot
/// whose default value means "unwritten", and an auto-max/stretch flag whose
/// default `1` likewise means "unwritten". The slot numbers and defaults are
/// the ones that reproduce every geometry element the platform writes on the
/// document fields of the native "1С:Управление торговлей 11.5.27.75" form
/// dumps without writing one it leaves out.
struct FormDocumentFieldGeometry {
    discriminator: &'static str,
    len: usize,
    /// `(slot, default)` for `<Width>`, `<Height>`, `<MaxWidth>`, `<MaxHeight>`.
    width: Option<(usize, &'static str)>,
    height: Option<(usize, &'static str)>,
    max_width: Option<usize>,
    max_height: Option<usize>,
    /// `slot` for the flags whose unwritten default is `1`.
    auto_max_width: Option<usize>,
    auto_max_height: Option<usize>,
    horizontal_stretch: Option<usize>,
    vertical_stretch: Option<usize>,
    /// Slot of the kind's own `<Edit>` flag, which shares the same `1` default.
    edit: Option<usize>,
    /// Slot of the kind's own `<EnableStartDrag>`, whose unwritten default is
    /// the opposite `0`.
    enable_start_drag: Option<usize>,
    /// Slot of the field's own `<Font>` tuple, where the kind has one.
    font: Option<usize>,
}

