pub(super) fn collect_form_table_column_names_for_table(
    fields: &[&str],
    columns: &mut BTreeMap<String, String>,
) {
    for field in fields {
        let field = field.trim();
        if !field.starts_with('{') {
            continue;
        }
        let Some(split_nested) = split_1c_braced_fields(field, 0) else {
            continue;
        };
        let revision_nested = normalize_form_item_record_revision(&split_nested);
        let nested = revision_nested.as_deref().unwrap_or(&split_nested);
        let wrapper = nested.first().map(|value| value.trim()).unwrap_or_default();
        if matches!(
            form_child_item_tag(wrapper, nested),
            Some("InputField" | "LabelField")
        ) && let Some(identity) = nested
            .get(1)
            .and_then(|field| split_1c_braced_fields(field, 0))
            && let (Some(id), Some(name)) = (
                identity.first().map(|value| value.trim().to_string()),
                parse_form_child_item_name(wrapper, &nested),
            )
        {
            columns.insert(id, name);
        }
        collect_form_table_column_names_for_table(&nested, columns);
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) fn parse_form_button_data_path(
    field: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    data_path_by_binding_key: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    match fields.as_slice() {
        [kind, owner] if kind.trim() == "1" => {
            let owner = split_1c_braced_fields(owner.trim(), 0)?;
            if owner.len() != 1 {
                return None;
            }
            attribute_names_by_id.get(owner.first()?.trim()).cloned()
        }
        [kind, owner, terminal] if kind.trim() == "2" => {
            let owner = split_1c_braced_fields(owner.trim(), 0)?;
            let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
            if terminal.len() != 1 {
                return None;
            }
            if owner.len() == 1 {
                if !matches!(terminal.first()?.trim(), "-5" | "-8") {
                    return None;
                }
                let attribute_name = attribute_names_by_id.get(owner.first()?.trim())?;
                return Some(format!("{attribute_name}.Ref"));
            }
            if owner.len() != 2 || owner.get(1)?.trim() != FORM_ITEM_TYPE_UUID {
                return None;
            }
            let marker = form_table_column_unresolvable_marker(
                owner.first()?.trim(),
                terminal.first()?.trim(),
                owner_scoped_bindings,
            );
            if let Some(data_path) = type_link_data_path_by_table_column.get(&(
                owner.first()?.trim().to_string(),
                terminal.first()?.trim().to_string(),
            )) {
                return Some(format!("{marker}{data_path}"));
            }
            resolve_form_item_current_data_path(
                owner.first()?.trim(),
                terminal.first()?.trim(),
                table_name_by_id,
                table_column_names_by_id,
                data_path_by_binding_key,
            )
            .map(|data_path| format!("{marker}{data_path}"))
        }
        _ => None,
    }
}

/// The `~` marker a data path onto a table item's column carries when the
/// column is outside the bound dynamic list's own resolvable-field universe.
///
/// The fact is the one `<UseAlways>` is measured against and the one the
/// attribute-scoped route already writes: a field the list cannot resolve
/// against its data source is spelled with the platform's `~` in front of the
/// whole path. Which route reached the column does not change that -- only the
/// namespace the column id is keyed in, and a table item's terminal is
/// numbered in the namespace of the attribute the table is bound to.
///
/// Evidence: Документооборот КОРП 3.0.21.3
/// `Catalogs/Файлы/Forms/РедактируемыеФайлы`, Button
/// `ОбщаяКоманда_ДополнительныеСведения` carries `{2,{6,02023637-…},{36}}`
/// against table item 6 (`Список`), bound to a manual-query dynamic list whose
/// `<MainTable>` is `InformationRegister.ФайлыВРабочемКаталогеКомпьютера`;
/// column 36 is `Ссылка`, which that main table does not hold, and the platform
/// writes `~Items.Список.CurrentData.Ссылка`.
fn form_table_column_unresolvable_marker(
    table_id: &str,
    column_id: &str,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> &'static str {
    if owner_scoped_bindings
        .unresolvable_table_columns
        .contains(&(table_id.to_string(), column_id.to_string()))
    {
        "~"
    } else {
        ""
    }
}

/// Resolves a bound-field slot whose owner is a *form item* rather than a form
/// attribute.
///
/// A kind-2 binding carries its owner as `{id}` for an attribute and as
/// `{id,02023637-…}` for a form item — the trailing literal is the form-item id
/// namespace already spelled out by [`FORM_ITEM_TYPE_UUID`]. Reading the item
/// form as an attribute id silently addresses an unrelated owner, so the two
/// shapes must be told apart before any attribute lookup.
///
/// Evidence: UT 11.5.27.75 `Catalogs/ВидыСделокСКлиентами/Forms/ФормаСписка`,
/// LabelField `Описание` carries `{2,{1,02023637-7868-4a5f-8576-835a76e0c9ba},{40}}`
/// against the `Список` dynamic-list table (form item 1, dynamic-list field 40)
/// and the platform writes `<DataPath>Items.Список.CurrentData.Описание</DataPath>`.
///
/// Global binding-key routes are deliberately not consulted here: the
/// column key of an item-scoped binding is only unique within its own table, so
/// a form-wide index would cross-wire sibling tables that reuse a key.
///
/// The terminal addresses the column either by its form binding id or by the
/// metadata uuid of the member it shows. The uuid form names the member
/// outright, so it is read straight off the metadata reference and never
/// through the type-link route table: that table records where a *choice link*
/// points, which is a different column whenever the two disagree. Evidence: UT
/// 11.5.27.75 `Documents/СправкаОПодтверждающихДокументах/Forms/ФормаДокумента`,
/// InputField `ПодтверждающиеДокументыБезРазбиенияВалюта` carries
/// `{2,{62,02023637-…},{0,b305196a-…}}`, whose uuid is
/// `Document.СправкаОПодтверждающихДокументах.TabularSection.
/// ПодтверждающиеДокументы.Attribute.ВалютаДокумента`, and the platform writes
/// `Items.ПодтверждающиеДокументы.CurrentData.ВалютаДокумента` while the route
/// table holds `…CurrentData.Валюта`.
fn resolve_form_item_scoped_current_data_path(
    field: &str,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    type_link_data_path_by_table_column: &BTreeMap<(String, String), String>,
    object_refs: &BTreeMap<String, String>,
    owner_scoped_bindings: &FormOwnerScopedBindingIndexes,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let [kind, owner, terminal] = fields.as_slice() else {
        return None;
    };
    if kind.trim() != "2" {
        return None;
    }
    let owner = split_1c_braced_fields(owner.trim(), 0)?;
    let terminal = split_1c_braced_fields(terminal.trim(), 0)?;
    if owner.len() != 2 || owner.get(1)?.trim() != FORM_ITEM_TYPE_UUID {
        return None;
    }
    let table_id = owner.first()?.trim();
    if let [marker, uuid] = terminal.as_slice() {
        // The additional-columns marker is a *column id*, not the `0` a
        // metadata terminal carries, so the terminal was condemned instead of
        // read against the table's own additional columns.
        if uuid
            .trim()
            .eq_ignore_ascii_case(FORM_VALUE_TABLE_COLUMN_BINDING_UUID)
        {
            return owner_scoped_bindings
                .table_additional_columns
                .get(&(table_id.to_string(), marker.trim().to_string()))?
                .clone();
        }
        if marker.trim() != "0" {
            return None;
        }
        return resolve_form_table_current_data_metadata_uuid_path(
            table_id,
            uuid.trim(),
            table_name_by_id,
            object_refs,
        );
    }
    if terminal.len() != 1 {
        return None;
    }
    let column_id = terminal.first()?.trim();
    let marker = form_table_column_unresolvable_marker(table_id, column_id, owner_scoped_bindings);
    if let Some(data_path) =
        type_link_data_path_by_table_column.get(&(table_id.to_string(), column_id.to_string()))
    {
        return Some(format!("{marker}{data_path}"));
    }
    let no_global_binding_paths = BTreeMap::new();
    resolve_form_item_current_data_path(
        table_id,
        column_id,
        table_name_by_id,
        table_column_names_by_id,
        &no_global_binding_paths,
    )
    .map(|data_path| format!("{marker}{data_path}"))
}

fn resolve_form_item_current_data_path(
    table_id: &str,
    binding_key: &str,
    table_name_by_id: &BTreeMap<String, String>,
    table_column_names_by_id: &BTreeMap<String, BTreeMap<String, String>>,
    data_path_by_binding_key: &BTreeMap<String, String>,
) -> Option<String> {
    let table_name = table_name_by_id.get(table_id)?;
    let field_name = if binding_key == "8" {
        "Ref".to_string()
    } else if let Some(field_name) = data_path_by_binding_key
        .get(binding_key)
        .and_then(|data_path| data_path.strip_prefix(table_name))
        .and_then(|field_name| field_name.strip_prefix('.'))
        .filter(|field_name| !field_name.is_empty())
    {
        normalize_form_table_column_name(table_name, field_name)
    } else if let Some(field_name) = table_column_names_by_id
        .get(table_id)
        .and_then(|columns| columns.get(binding_key))
    {
        normalize_form_table_column_name(table_name, field_name)
    } else {
        return None;
    };
    Some(format!("Items.{table_name}.CurrentData.{field_name}"))
}

#[cfg(test)]
pub(super) fn extract_form_command_interface(
    trailing: &[String],
    object_refs: &BTreeMap<String, String>,
) -> Option<FormCommandInterface> {
    extract_form_command_interface_with_commands(trailing, &[], object_refs)
}

#[cfg(test)]
pub(super) fn extract_form_command_interface_with_commands(
    trailing: &[String],
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
) -> Option<FormCommandInterface> {
    extract_form_command_interface_with_context(
        trailing,
        commands,
        object_refs,
        &BTreeMap::new(),
        &InformationRegisterMasterDimensionIndex::new(),
        None,
        &[],
        &FormChildItemIndexes::default(),
        None,
    )
}

#[allow(clippy::too_many_arguments)]
pub(super) fn extract_form_command_interface_with_context(
    trailing: &[String],
    commands: &[FormCommand],
    object_refs: &BTreeMap<String, String>,
    information_register_field_refs: &InformationRegisterFieldReferenceIndex,
    information_register_master_dimensions: &InformationRegisterMasterDimensionIndex,
    form_owner_reference: Option<&str>,
    attributes: &[FormAttribute],
    child_item_indexes: &FormChildItemIndexes,
    metadata_command_refs: Option<&BTreeMap<String, MetadataCommandReference>>,
) -> Option<FormCommandInterface> {
    let attribute_names_by_id = attributes
        .iter()
        .map(|attribute| (attribute.id.clone(), attribute.name.clone()))
        .collect::<BTreeMap<_, _>>();
    let empty_metadata_command_refs = BTreeMap::new();
    let context = FormCommandInterfaceParseContext {
        commands,
        object_refs,
        information_register_field_refs,
        information_register_master_dimensions,
        form_owner_reference,
        attribute_names_by_id: &attribute_names_by_id,
        child_item_indexes,
        metadata_command_refs: metadata_command_refs.unwrap_or(&empty_metadata_command_refs),
    };
    let mut command_bar = Vec::new();
    let mut navigation_panel = Vec::new();
    for (trailing_slot, field) in trailing.iter().enumerate() {
        let Some(container) =
            parse_form_command_interface_container(trailing_slot, field, &context)
        else {
            continue;
        };
        command_bar.extend(container.command_bar);
        navigation_panel.extend(container.navigation_panel);
    }
    (!command_bar.is_empty() || !navigation_panel.is_empty()).then_some(FormCommandInterface {
        command_bar,
        navigation_panel,
    })
}

pub(super) struct FormCommandInterfaceParseContext<'a> {
    commands: &'a [FormCommand],
    object_refs: &'a BTreeMap<String, String>,
    information_register_field_refs: &'a InformationRegisterFieldReferenceIndex,
    information_register_master_dimensions: &'a InformationRegisterMasterDimensionIndex,
    form_owner_reference: Option<&'a str>,
    attribute_names_by_id: &'a BTreeMap<String, String>,
    child_item_indexes: &'a FormChildItemIndexes,
    /// Whether each target metadata object declares
    /// `<UseStandardCommands>`. Empty behaves as "unknown, assume true"
    /// (today's behaviour) for every uuid it does not carry.
    metadata_command_refs: &'a BTreeMap<String, MetadataCommandReference>,
}

pub(super) fn parse_form_command_interface_container(
    trailing_slot: usize,
    field: &str,
    context: &FormCommandInterfaceParseContext<'_>,
) -> Option<FormCommandInterface> {
    let fields = split_1c_braced_fields(field, 0)?;
    let declared_item_count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let typed_item_count = fields
        .iter()
        .skip(2)
        .filter(|field| form_command_interface_item_schema(field).is_some())
        .count();
    let schema = FormCommandInterfaceContainerSchema::from_raw_layout(
        trailing_slot,
        fields.first()?.trim(),
        fields.len(),
        declared_item_count,
        typed_item_count,
    )?;
    let mut command_bar = Vec::new();
    let mut navigation_panel = Vec::new();
    for field in fields.iter().skip(2) {
        if let Some(item) = parse_form_command_interface_item(field, context) {
            match schema.owner() {
                FormCommandInterfaceContainerOwner::CommandBar => command_bar.push(item),
                FormCommandInterfaceContainerOwner::NavigationPanel => navigation_panel.push(item),
            }
        }
    }
    if command_bar.is_empty() && navigation_panel.is_empty() {
        return None;
    }
    Some(FormCommandInterface {
        command_bar,
        navigation_panel,
    })
}

pub(super) fn parse_form_command_interface_item(
    field: &str,
    context: &FormCommandInterfaceParseContext<'_>,
) -> Option<FormCommandInterfaceItem> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    FormCommandInterfaceItemSchema::from_raw_layout(
        fields.first()?.trim(),
        fields.len(),
        fields.get(4)?.trim(),
        fields.get(7)?.trim(),
    )?;
    form_command_interface_visibility_schema(fields.get(8)?)?;
    let command = parse_form_command_interface_command(fields.get(2)?, context)?;
    let item_type = parse_form_command_interface_item_type(fields.get(4).copied())?;
    let attribute = parse_form_command_interface_attribute(
        fields.get(3)?,
        context.attribute_names_by_id,
        context.child_item_indexes,
    )?;
    let command_group = fields
        .get(5)
        .and_then(|field| parse_form_command_group_reference(field, context.object_refs));
    let index = fields
        .get(6)
        .and_then(|value| value.trim().parse::<usize>().ok())
        .filter(|index| *index > 0);
    let default_visible = match fields.get(7).map(|value| value.trim()) {
        Some("0") => Some(false),
        Some("1") => Some(true),
        _ => None,
    }
    .filter(|visible| !*visible);
    // Slot 8 is always shaped like a rights tuple (validated above), but the
    // platform only surfaces it as `<Visible>` when slot 7 itself was written
    // `false`: across mdm/ws/ssl/sslbase/ut/uh (14 000+ items) every item whose
    // `<DefaultVisible>` is unwritten also carries no `<Visible>`, even when
    // slot 8 decodes to a non-default `common=false` -- e.g. MDM_Management
    // `Catalogs/ТипыБазДанных/Forms/ФормаЭлемента`, whose `Catalog.СправочникиБД`
    // item has slot 7 `1` (default_visible unwritten) and slot 8
    // `{0,{0,{"B",0},0}}` (common=false) yet native writes no `<Visible>` at
    // all. A slot-7 `0` sibling with the identical slot-8 shape in the same
    // form (`Task.ЗадачаИсполнителя.Command.Выполнено`, sslbase corpus) does
    // get `<Visible><xr:Common>false</xr:Common></Visible>`, so the gate is on
    // slot 7, not a coincidence of slot 8's bits.
    let visible = if default_visible.is_some() {
        parse_form_command_interface_visibility(fields.get(8)?, context.object_refs)?
    } else {
        None
    };
    Some(FormCommandInterfaceItem {
        command,
        item_type,
        attribute,
        command_group,
        index,
        default_visible,
        visible,
    })
}

pub(super) fn parse_form_command_interface_attribute(
    field: &str,
    attribute_names_by_id: &BTreeMap<String, String>,
    child_item_indexes: &FormChildItemIndexes,
) -> Option<Option<String>> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.len() == 1 && fields.first()?.trim() == "0" {
        return Some(None);
    }
    if fields.len() != 3 || fields.first()?.trim() != "2" {
        return None;
    }
    let attribute = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    let binding = split_1c_braced_fields(fields.get(2)?.trim(), 0)?;
    if attribute.len() != 1 || binding.len() != 1 {
        return None;
    }
    if binding.first()?.trim() == "-8" {
        let attribute_name = attribute_names_by_id.get(attribute.first()?.trim())?;
        return Some(Some(format!("{attribute_name}.Ref")));
    }
    parse_form_bound_data_path(
        field,
        attribute_names_by_id,
        &child_item_indexes.table_name_by_id,
        &child_item_indexes.table_column_names_by_id,
        &child_item_indexes.bound_table_path_by_binding_key,
        &child_item_indexes.table_column_names_by_binding_key,
    )
    .map(Some)
}

pub(super) fn form_command_interface_item_schema(
    field: &str,
) -> Option<FormCommandInterfaceItemSchema> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let schema = FormCommandInterfaceItemSchema::from_raw_layout(
        fields.first()?.trim(),
        fields.len(),
        fields.get(4)?.trim(),
        fields.get(7)?.trim(),
    )?;
    form_command_interface_visibility_schema(fields.get(8)?)?;
    Some(schema)
}

pub(super) fn form_command_interface_visibility_schema(
    field: &str,
) -> Option<FormCommandInterfaceVisibilitySchema> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let scope = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    parse_form_typed_bool(scope.get(1)?)?;
    let role_count = scope.get(2)?.trim().parse::<usize>().ok()?;
    let typed_role_count = scope
        .get(3..)?
        .chunks_exact(2)
        .filter(|pair| {
            parse_non_zero_uuid(pair[0].trim()).is_some()
                && parse_form_typed_bool(pair[1]).is_some()
        })
        .count();
    FormCommandInterfaceVisibilitySchema::from_raw_layout(
        fields.first()?.trim(),
        fields.len(),
        scope.first()?.trim(),
        scope.len(),
        role_count,
        typed_role_count,
    )
}

pub(super) fn parse_form_command_interface_visibility(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<Option<FormCommandInterfaceVisibility>> {
    let schema = form_command_interface_visibility_schema(field)?;
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let scope = split_1c_braced_fields(fields.get(1)?.trim(), 0)?;
    let common = parse_form_typed_bool(scope.get(1)?)?;
    let mut role_values = Vec::with_capacity(schema.role_count());
    for pair in scope.get(3..)?.chunks_exact(2) {
        let uuid = parse_non_zero_uuid(pair[0].trim())?;
        let role = object_refs.get(&uuid)?.strip_prefix("Role.")?;
        role_values.push((format!("Role.{role}"), parse_form_typed_bool(pair[1])?));
    }
    Some(
        (!common || !role_values.is_empty()).then_some(FormCommandInterfaceVisibility {
            common,
            role_values,
        }),
    )
}

/// A per-role permission of a form attribute, an attribute column or a form
/// command: the common answer plus the roles that override it.
///
/// The platform stores it in exactly the tuple the command-interface
/// visibility uses -- `{0,{0,{"B",<common>},<n>,<role uuid>,{"B",<value>},…}}`
/// -- so the reader below is the command-interface reader, not a second table
/// for the same fact.
pub(super) type FormRightsSetting = FormCommandInterfaceVisibility;

/// The rights tuple a form attribute, attribute column or command slot holds.
///
/// `None` means the slot is not a rights tuple at all; `Some(None)` means it is
/// the default one (`common` true with no role overriding it), which the
/// platform leaves unwritten.
pub(super) fn parse_form_rights_setting(
    field: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<Option<FormRightsSetting>> {
    parse_form_command_interface_visibility(field, object_refs)
}

/// `<View>`/`<Edit>`/`<Use>` -- a rights setting under the given element name.
pub(super) fn format_form_rights_setting_xml(
    name: &str,
    rights: &FormRightsSetting,
    indent: &str,
) -> String {
    let mut xml = format!("{indent}<{name}>\r\n");
    xml.push_str(&format!(
        "{indent}\t<xr:Common>{}</xr:Common>\r\n",
        xml_bool(rights.common)
    ));
    for (role, value) in &rights.role_values {
        xml.push_str(&format!(
            "{indent}\t<xr:Value name=\"{}\">{}</xr:Value>\r\n",
            escape_xml_text(role),
            xml_bool(*value)
        ));
    }
    xml.push_str(&format!("{indent}</{name}>\r\n"));
    xml
}

pub(super) fn parse_form_typed_bool(field: &str) -> Option<bool> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    if fields.len() != 2 || fields.first().map(|value| value.trim()) != Some(r#""B""#) {
        return None;
    }
    match fields.get(1)?.trim() {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

pub(super) fn parse_form_command_interface_item_type(field: Option<&str>) -> Option<&'static str> {
    match field.map(str::trim) {
        Some("0") => Some("Auto"),
        Some("1") => Some("Added"),
        _ => None,
    }
}

/// The name a `{kind, uuid}` command-interface record spells, before the raw
/// `kind:uuid` fallback its caller applies.
///
/// The arms live in a function of their own so that a `?` inside one answers
/// *this* reading with `None`.  Held inline, the very same `?` returned from
/// `parse_form_command_interface_command` itself and jumped over the caller's
/// fallback: `3075f50` measured that the platform keeps the raw sentinel for a
/// uuid that names nothing in the configuration and wrote the fallback for
/// every kind, but slots 1, 2, 3 and 4 each resolve their target with
/// `context.object_refs.get(&uuid)?`, so on exactly the records the fallback
/// was written for the function was already gone and the item was dropped.
/// Only the kinds whose arms carry their own copy of the fallback -- `0`,
/// `5`, `6`, `7` -- and the kinds with no arm at all ever reached it.
fn form_command_interface_command_named(
    kind: &str,
    target: Option<&str>,
    context: &FormCommandInterfaceParseContext<'_>,
) -> Option<String> {
    match kind {
        "0" => {
            let Some(target) = target else {
                return Some("0".to_string());
            };
            if target == "0" || target == "00000000-0000-0000-0000-000000000000" {
                Some("0".to_string())
            } else {
                let uuid = parse_non_zero_uuid(target)?;
                context
                    .object_refs
                    .get(&uuid)
                    .map(|reference| {
                        // A filter criterion carries no command of its own, so this
                        // slot names its "open by value" standard command; every
                        // other target in this slot is named by the same function
                        // the button reader uses.
                        //
                        // The slot is not "already a command reference": most of
                        // its targets are, and those the function returns
                        // unchanged, but a target that is a metadata object
                        // itself needs that object's own standard command
                        // spelled. Census of every `<Command>` a native
                        // `<CommandInterface>` item carries across the eight
                        // stand corpora -- 15 705 of them -- finds not one bare
                        // metadata reference: every one is a command reference,
                        // a `.StandardCommand.` name, a bare number or the raw
                        // `kind:uuid` sentinel. Writing the reference bare was
                        // therefore always wrong, and it is what the four items
                        // ERP УХ writes as `Document.ПредложениеПоставщика.
                        // StandardCommand.OpenList`,
                        // `DocumentJournal.ДвижениеИнвестиций.…OpenList` and two
                        // catalogue `…OpenList` names were coming out as.
                        if is_top_level_reference_of_kind(reference, "FilterCriterion") {
                            format!("{reference}.StandardCommand.OpenByValue")
                        } else {
                            form_object_reference_command_name(reference)
                        }
                    })
                    .or_else(|| form_standard_command_name(&uuid))
                    // Nothing named this target: the platform still writes the
                    // item, as the raw `kind:uuid` sentinel rather than a name it
                    // cannot construct -- the object-level
                    // `command_interface_command_name` sibling this mirrors has
                    // always done the same. UT
                    // `Documents/ЗаявкаНаИзменениеНСИ/Forms/ФормаВыбора`:
                    // `0:1d3cba0d-8887-4564-a9a2-6df75e80e775` is not any
                    // metadata object, command or button uuid this reader
                    // knows, and native keeps it literal; before this fallback
                    // the whole `<CommandBar>` (both its items) went unwritten
                    // because every item in it failed to resolve.
                    .or_else(|| Some(format!("0:{uuid}")))
            }
        }
        // Slots 1 and 2 are pure family rules, read through the one shared
        // grammar so this reader and the button reader cannot disagree about the
        // same `{kind, uuid}` record again. An unresolved uuid still hard-fails
        // here (unlike kind `0`): every evidenced record of this shape names a
        // real metadata object of the current configuration, never a raw
        // platform constant, so a miss is unproven rather than the target
        // simply lacking a name.
        "1" | "2" => {
            let uuid = parse_non_zero_uuid(target?)?;
            let reference = context.object_refs.get(&uuid)?;
            if !form_command_interface_target_use_standard_commands(&uuid, context) {
                return Some(format!("{kind}:{uuid}"));
            }
            let name = form_object_family_standard_command_name(
                kind,
                reference,
                FormCommandRecordReader::CommandInterfaceItem,
            )?;
            // The same declaration the button reads: a target whose `<BasedOn>`
            // is empty has no "create based on" command, and the platform keeps
            // the raw sentinel. ERP УХ 3.2.12.6 writes
            // `2:2aba076a-…`/`2:d72012cf-…` on the eight
            // `Documents/ВерсияСоглашения*` forms whose submenu names
            // `Document.УдалитьЗаявкаНаКорректировкуЛимитов` and
            // `Document.УдалитьКорректировкаЛимитов`, both `<BasedOn/>`.
            if !form_command_target_declares_standard_command(
                &uuid,
                &name,
                context.metadata_command_refs,
            ) {
                return Some(format!("{kind}:{uuid}"));
            }
            Some(name)
        }
        "3" => {
            let target = target?;
            let uuid = parse_non_zero_uuid(target)?;
            // The gate runs first, ahead of the register rule and not behind
            // it. A target with no standard commands has no "open by value"
            // either, and the rule was naming one anyway on every slot it
            // reached before the gate. ERP УХ 3.2.12.6: all fifteen registers
            // this reader named through the rule and the platform left as the
            // raw sentinel declare `UseStandardCommands=false` --
            // `ОбработанныеОбъектыБД` (13 items), `ИзмененныеОбъектыДляВыгрузки`
            // (6), `НастройкиОповещений` (5), `СверкаВГОЗакрыта`,
            // `ОбъектыХранимыхФайлов`, `ПроцедурыРасчетов`,
            // `ИменаФайловИКаталогов` and eight more, one item each. Not one
            // register the platform does name through the rule declares it.
            if !form_command_interface_target_use_standard_commands(&uuid, context) {
                return Some(format!("{kind}:{uuid}"));
            }
            if let Some(name) =
                resolve_information_register_open_by_value_command(kind, target, context)
            {
                return Some(name);
            }
            let reference = context.object_refs.get(&uuid)?;
            // A catalog names its "create based on" command from slot 3, where a
            // document or business process names the same command from slot 2 --
            // and it reads the same empty-`<BasedOn>` declaration there.
            form_object_family_standard_command_name(
                kind,
                reference,
                FormCommandRecordReader::CommandInterfaceItem,
            )
            .map(|name| {
                if form_command_target_declares_standard_command(
                    &uuid,
                    &name,
                    context.metadata_command_refs,
                ) {
                    name
                } else {
                    format!("{kind}:{uuid}")
                }
            })
            .or_else(|| {
                (reference.starts_with("CommonCommand.") || reference.contains(".Command."))
                    .then(|| reference.clone())
            })
        }
        "4" => {
            let target = target?;
            let uuid = parse_non_zero_uuid(target)?;
            let reference = context.object_refs.get(&uuid)?;
            if !form_command_interface_target_use_standard_commands(&uuid, context) {
                return Some(format!("{kind}:{uuid}"));
            }
            // The same declaration slots 1, 2 and 3 already read: a target
            // that cannot have what the command opens by has no such command,
            // and the platform keeps the raw sentinel.
            if let Some(name) = form_object_family_standard_command_name(
                kind,
                reference,
                FormCommandRecordReader::CommandInterfaceItem,
            ) {
                return Some(
                    if form_command_target_declares_standard_command(
                        &uuid,
                        &name,
                        context.metadata_command_refs,
                    ) {
                        name
                    } else {
                        format!("{kind}:{uuid}")
                    },
                );
            }
            resolve_information_register_open_by_value_command(kind, target, context)
        }
        // Slots 5, 6 and 7 carry nothing but this command; slots 3 and 4 share
        // theirs with the object commands handled above. The gate belongs here
        // too: the rule resolves its target through `object_refs` like every
        // other, and ERP УХ leaves `5:1c2ef491-…`, `6:1c2ef491-…`,
        // `5:917a207a-…`, `6:917a207a-…`, `5:67b0794f-…`, `5:9f6e69eb-…` and
        // `5:1f15119b-…` raw -- every one of them a register that declares
        // `UseStandardCommands=false`.
        "5" | "6" | "7" => {
            let target = target?;
            let uuid = parse_non_zero_uuid(target)?;
            if !form_command_interface_target_use_standard_commands(&uuid, context) {
                return Some(format!("{kind}:{uuid}"));
            }
            if let Some(name) =
                resolve_information_register_open_by_value_command(kind, target, context)
            {
                return Some(name);
            }
            // A well-formed uuid that names nothing in this configuration is
            // the second case the platform cannot construct a name for, and it
            // keeps the raw `kind:uuid` sentinel for it too -- the same
            // fallback kind `0` already documents, and the same spelling the
            // `UseStandardCommands` gate just above writes. ERP УХ
            // MDM_Management's `Documents/ЗаявкаНаИзменениеНСИ/Forms/ФормаДокумента`
            // carries `5:85128f52-4d52-496d-b679-83a44b512923`, whose uuid
            // occurs nowhere else in the exported tree -- so the gate above
            // cannot answer for it (an unknown uuid reads as "declares
            // standard commands") -- and native writes it literally. Refusing
            // it here did not merely drop the item: it was the only item of
            // that form's `<NavigationPanel>`, so the whole container went
            // unwritten.
            (!context.object_refs.contains_key(&uuid)).then(|| format!("{kind}:{uuid}"))
        }
        _ => None,
    }
}

pub(super) fn parse_form_command_interface_command(
    field: &str,
    context: &FormCommandInterfaceParseContext<'_>,
) -> Option<String> {
    let fields = split_1c_braced_fields(field.trim(), 0)?;
    let kind = fields.first()?.trim();
    let target = fields.get(1).map(|value| value.trim());
    if kind != "0"
        && let Some(uuid) = target.and_then(parse_non_zero_uuid)
        && let Some(command) = context
            .commands
            .iter()
            .find(|command| command.id == kind && command.reference_uuid == uuid)
    {
        return Some(format!("Form.Command.{}", command.name));
    }
    if let Some(name) = form_command_record_single_field_name(&fields) {
        return Some(name);
    }
    let named = form_command_interface_command_named(kind, target, context);
    // A well-formed uuid that names nothing in this configuration is a
    // reference the platform cannot construct a name for, and it writes the raw
    // `kind:uuid` sentinel for it — in *every* record slot, not only in the
    // three the rule was first measured in. The `0` arm and the `5`/`6`/`7` arm
    // of `form_command_interface_command_named` each carry their own copy of
    // it; this is the same reading, applied once for every kind, so a slot
    // those arms leave unresolved no longer takes the whole item down with it.
    //
    // Evidence: ERP УХ 3.2.12.6, the whole differing set. The platform writes
    // 65 `<Command>` values inside `<CommandInterface>` that this export does
    // not, on 21 forms; 44 distinct uuids carry them, and a scan of all 56 697
    // metadata documents of the configuration finds 38 of the 44 nowhere at
    // all — they name no object, no command and no subsystem. They are spelled
    // `1:`, `2:`, `3:`, `4:`, `5:` and `8:`, so the sentinel is not a property
    // of the slot number. `Catalogs/ОбъектыЭксплуатации/Forms/ФормаЭлемента`
    // alone carries fifteen of them, `Catalogs/Сценарии/Forms/ФормаЭлемента`
    // seven; in each case the refusal dropped the whole `<Item>`, and where the
    // refused item was the container's only one it dropped the container.
    //
    // The two uuids that *do* name something stay refused here. Both are in
    // ERP УХ 3.2.12.6 `Catalogs/Сценарии/Forms/ФормаЭлемента` --
    // `5:f18047cf-…` (`InformationRegister.ПараметрыУчетаВНАМСФО`) and
    // `8:50635584-…` (`InformationRegister.ПротоколыОбъектов`) -- and the
    // platform writes the sentinel for them too. Dropping this condition would
    // reproduce both, but it would also spell a sentinel for every record this
    // reader merely fails to name -- a register whose open-by-value dimension
    // is ambiguous, say -- where the platform does write a name. Those are two
    // different states and nothing measured here separates them, so the two
    // records stay unwritten rather than joined by fabricated ones.
    named.or_else(|| {
        let uuid = target.and_then(parse_non_zero_uuid)?;
        (!context.object_refs.contains_key(&uuid)).then(|| format!("{kind}:{uuid}"))
    })
}

